-- ===========================================================================
--  tables_indexes_comments_sequences.postgres.sql
--  Transformacion 1:1 del script Oracle tables_indexes_comments_sequences (2).sql
--  al dialecto PostgreSQL 14+ (identidad compatible con PG 10+).
--
--  Reglas aplicadas:
--    * NUMBER(p[,s])           -> NUMERIC(p[,s])
--    * VARCHAR2(n [CHAR|BYTE]) -> VARCHAR(n)     (PostgreSQL cuenta chars)
--    * CLOB / NCLOB            -> TEXT
--    * BLOB                    -> BYTEA
--    * TIMESTAMP[(6)]          -> TIMESTAMP
--    * GENERATED BY DEFAULT AS IDENTITY  (sintaxis ya compatible)
--    * DEFAULT SYSTIMESTAMP    -> DEFAULT CURRENT_TIMESTAMP
--    * DEFAULT SYSDATE         -> DEFAULT CURRENT_DATE
--    * CHECK / UNIQUE / PK / FK / ON DELETE CASCADE / ON DELETE SET NULL
--      y DEFERRABLE INITIALLY DEFERRED son identicos entre Oracle y PG.
--    * COMMENT ON <TABLE|COLUMN> sin comillas  ->  tabla.col
--      (PostgreSQL dobla identificadores sin comillas a minusculas).
--    * CREATE [UNIQUE] INDEX, ALTER TABLE ADD CONSTRAINT  son sintaxis
--      directamente portables.
--
--  Limitaciones preservadas del original (no se arreglan):
--    * PK compuesta (2 tablas — TENTE_USUARIO y TSEDE_USUARIO con PK sobre
--      FK_TENTE/FK_TROL/FK_TUSUARIO y FK_TSEDE/FK_TROL/FK_TUSUARIO): PG no
--      puede auto-incrementar una PK compuesta; las columnas heredan su valor
--      por JOIN con las tablas padre. Si se quiere IDENTITY sobre cada FK
--      puede agregarse manualmente, pero rompe la semantica del modelo.
--    * Algunos indices (U_TSEDE_2, U_TENCUESTA_1, U_TGRUPO_1,
--      U_TASIGNATURA_1, U_TPREGUNTA_1, U_TRESPUESTA_1, U_TASIGNATURA_PLAN_1,
--      U_TASIGNATURA_DEFINITIVA_1, U_TASIGNATURA_NOTA_IDX1,
--      TAREA_NOTA_IDX1, UK_TCALENDARIO_DETALLE_1, U_TACTIVIDAD_1,
--      U_TMATRICULA_ASIGNATURA_1, UK_TACTIVIDAD_NOTA_1)
--      duplican literalmente una UNIQUE constraint declarada en la tabla.
--      PG los creara, pero aparecen como redundant en herramientas de
--      auditoria — se conservan para mantener fidelidad 1:1.
--    * TSESION: el origen declara el PK inline (CONSTRAINT TSESION_PK
--      PRIMARY KEY) y luego ALTER TABLE ... ADD PRIMARY KEY. Oracle lo
--      acepta, PG no. El ALTER queda anotado como comentario.
--    * Tablas-puerta sin PK declarado (TMENSAJE_ENVIADO_ARCHIVO,
--      TMENSAJE_RECIBIDO_ARCHIVO, TNOTICIA_ENVIADA_ARCHIVO,
--      TNOTICIA_RECIBIDO_ARCHIVO): heredan su unicidad del FK al padre;
--      no se les agrega IDENTITY artificial.
--
--  Cobertura final de IDs auto-incrementales:
--    * 123 columnas PK simple: NUMERIC(p) GENERATED BY DEFAULT AS IDENTITY
--      (88 que ya estaban en el origen + 35 que el script agrega para
--      que el archivo sea auto-contenido en PG).
--    * 2 columnas que NO reciben IDENTITY: las PKs de TENTE_USUARIO y
--      TSEDE_USUARIO (composite keys - PG no soporta IDENTITY alli).
--
--  Origen de datos del proyecto (no se migra en este archivo):
--    inicializadores academico_test, docker-compose, postgrest.conf, init/
-- ===========================================================================

SET client_min_messages TO WARNING;

-- ---------------------------------------------------------------------------
--  Esquema: mantenemos los nombres en MAYUSCULAS usando identificadores
--  entrecomillados para preservar la sensibilidad de caso de Oracle.
-- ---------------------------------------------------------------------------

CREATE SCHEMA IF NOT EXISTS academico_test;
SET search_path TO academico_test, public;

-- ---------------------------------------------------------------------------
--  Reconciliacion de esquemas preexistentes.
--
--  Todos los CREATE TABLE de abajo son IF NOT EXISTS, asi que en una BD
--  donde academico_test ya fue creado FUERA de Flyway (el servidor de
--  test tiene 147 tablas cargadas con ~16M filas de datos importados)
--  el CREATE es un no-op y la columna ACTIVE nunca aparece. Los indices
--  parciales `WHERE ACTIVE = true` que siguen a cada tabla fallan
--  entonces con 42703 "column active does not exist" y tumban la
--  migracion completa.
--
--  Este bloque agrega ACTIVE a lo que ya existe ANTES de que se cree el
--  primer indice. En una BD limpia el loop no encuentra tablas y no
--  hace nada — cada CREATE TABLE ya trae su ACTIVE. En PostgreSQL 11+
--  un ADD COLUMN con DEFAULT no reescribe la tabla (default rapido en
--  el catalogo), asi que esto es barato incluso sobre tactividad_nota
--  (3.6M filas).
-- ---------------------------------------------------------------------------
DO $reconcile$
DECLARE
    t record;
BEGIN
    FOR t IN
        SELECT tablename
          FROM pg_tables
         WHERE schemaname = 'academico_test'
    LOOP
        EXECUTE format(
            'ALTER TABLE academico_test.%I '
            'ADD COLUMN IF NOT EXISTS ACTIVE BOOLEAN DEFAULT TRUE NOT NULL',
            t.tablename);
    END LOOP;
END
$reconcile$;

-- ---------------------------------------------------------------------------
--  Domain types: sustituyen CHECK constraints de dos valores en columnas
--  muy repetidas. Permiten que information_schema.domains reporte el dominio
--  semantico (bool_sn, estado_ai, ...) y que PostgREST/OpenAPI lo exponga
--  como enum en lugar de string.
--
--  Solo se convierten checks con EXACTAMENTE 2 valores. Checks con 3+ valores
--  (TSEDE_CONVENIO, TVIDEO_CLASE, TSEDE_CONVENIO_MATRICULA, TVIDEO_USUARIOS
--  perfil, TTRASLADO_ESTUDIANTE) permanecen como CHECK IN (...) en linea.
-- ---------------------------------------------------------------------------

-- Si/No (boolean estilo colombiano). 40+ columnas lo usan.
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type t WHERE t.typname = 'bool_sn') THEN
  CREATE DOMAIN bool_sn AS VARCHAR(1)
    CHECK (VALUE IN ('S', 'N'));
  END IF;
END $$;

-- Activo/Inactivo (estado logico corto). 7 columnas.
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type t WHERE t.typname = 'estado_ai') THEN
  CREATE DOMAIN estado_ai AS VARCHAR(1)
    CHECK (VALUE IN ('A', 'I'));
  END IF;
END $$;

-- Activo/Cerrado (estado de evaluacion). 1 columna.
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type t WHERE t.typname = 'estado_ac') THEN
  CREATE DOMAIN estado_ac AS VARCHAR(1)
    CHECK (VALUE IN ('A', 'C'));
  END IF;
END $$;

-- Activo/Inactivo (estado de tablas de lookup TLV_ESTADO). 2 columnas.
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type t WHERE t.typname = 'estado_activo_inactivo') THEN
  CREATE DOMAIN estado_activo_inactivo AS VARCHAR(12)
    CHECK (VALUE IN ('ACTIVO', 'INACTIVO'));
  END IF;
END $$;

-- Nodo curricular (area tecnica vs academica). 1 columna.
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type t WHERE t.typname = 'nodo_curricular') THEN
  CREATE DOMAIN nodo_curricular AS VARCHAR(2)
    CHECK (VALUE IN ('AS', 'AR'));
  END IF;
END $$;

-- Titulacion del acta de grado (BACHILLER o vacio = sin titulo).
-- El espacio se conserva como valor valido para fidelidad 1:1 con Oracle.
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type t WHERE t.typname = 'titulacion_grado') THEN
  CREATE DOMAIN titulacion_grado AS VARCHAR(9)
    CHECK (VALUE IN (' ', 'BACHILLER'));
  END IF;
END $$;

-- ===========================================================================
--  Esquema academico (tablas, indices, comentarios, secuencias).
