-- --------------------------------------------------------------------------
--  Tabla: TENTE
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TENTE (
  PK_ENTE BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  NIT VARCHAR(30) NOT NULL,
  NOMBRE VARCHAR(130) NOT NULL,
  ESTADO estado_ai DEFAULT 'A'  NOT NULL,
  FK_TMUNICIPIO BIGINT NOT NULL,
  FK_TENTE_PADRE BIGINT,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TENTE PRIMARY KEY (PK_ENTE),
  CONSTRAINT U_TENTE_1 UNIQUE (NIT),
  CONSTRAINT U_TENTE_2 UNIQUE (NOMBRE),
  CONSTRAINT FK_TENTE_2 FOREIGN KEY (FK_TENTE_PADRE) REFERENCES TENTE (PK_ENTE)
);

--  Indices (3)
CREATE INDEX IF NOT EXISTS IDX_TENTE_5 ON TENTE (FK_TMUNICIPIO) ;
CREATE INDEX IF NOT EXISTS IDX_TENTE_6 ON TENTE (FK_TENTE_PADRE) ;
CREATE INDEX IF NOT EXISTS IDX_TENTE_ACTIVE ON TENTE (PK_ENTE) WHERE ACTIVE = true ;

--  Comentarios de columna (5)
COMMENT ON COLUMN TENTE.PK_ENTE IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TENTE.FK_TMUNICIPIO IS 'Llave foranea a tabla TMUNICIPIO';
COMMENT ON COLUMN TENTE.FK_TENTE_PADRE IS 'Llave foranea a tabla TENTE_PADRE';

