  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL
);

--  Indices (1)
CREATE INDEX IF NOT EXISTS IDX_TLISTA_VALOR_ACTIVE ON TLISTA_VALOR (PK_LISTA_VALOR) WHERE ACTIVE = true ;

--  Comentarios de columna (3)
COMMENT ON COLUMN TLISTA_VALOR.PK_LISTA_VALOR IS 'Llave primaria de la tabla';

--  Comentarios de tabla
COMMENT ON TABLE TLISTA_VALOR IS 'Lista de elementos seleccionables';

