-- --------------------------------------------------------------------------
--  Tabla: TPERIODO_ACADEMICO
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TPERIODO_ACADEMICO (
  PK_TPERIODO_ACADEMICO BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TPERIODO_ACADEMICO BIGINT,
  FK_TANO_LECTIVO BIGINT NOT NULL,
  FK_TLV_ESTADO BIGINT NOT NULL,
  FK_TSEDE BIGINT NOT NULL,
  FECHA_INICIO DATE NOT NULL,
  FECHA_FIN DATE NOT NULL,
  FECHA_LIMITE_MATRICULA DATE NOT NULL,
  FK_TLV_JORNADA BIGINT NOT NULL,
  RESERVA bool_sn DEFAULT 'S' NOT NULL,
  BLOQUES_POR_DEFECTO BIGINT DEFAULT 0 NOT NULL,
  NOMBRE VARCHAR(130),
  HORA_INICIO TIME NOT NULL,
  HORA_FIN TIME NOT NULL,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT FINAL_TPERIODO_ACADEMICO CHECK (FECHA_FIN >= FECHA_INICIO),
  CONSTRAINT FINAL_TPERIODO_ACADEMICO_1 CHECK (FECHA_LIMITE_MATRICULA >= FECHA_INICIO AND FECHA_LIMITE_MATRICULA <= FECHA_FIN),
  CONSTRAINT HORA_TPERIODO_ACADEMICO CHECK (HORA_FIN >= HORA_INICIO),
  CONSTRAINT PK_PERIODO_ACADEMICO PRIMARY KEY (PK_TPERIODO_ACADEMICO),
  CONSTRAINT U_TPERIODO_ACADEMICO_1 UNIQUE (FK_TANO_LECTIVO, FK_TSEDE, NOMBRE),
  CONSTRAINT FK_TPERIODO_ACADEMICO_3 FOREIGN KEY (FK_TLV_ESTADO) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TPERIODO_ACADEMICO_2 FOREIGN KEY (FK_TANO_LECTIVO) REFERENCES TANO_LECTIVO (PK_ANO_LECTIVO),
  CONSTRAINT FK_TPERIODO_ACADEMICO_1 FOREIGN KEY (FK_TPERIODO_ACADEMICO) REFERENCES TPERIODO_ACADEMICO (PK_TPERIODO_ACADEMICO),
  CONSTRAINT FK_TPERIODO_ACADEMICO_4 FOREIGN KEY (FK_TSEDE) REFERENCES TSEDE (PK_TSEDE),
  CONSTRAINT FK_TPERIODO_ACADEMICO_5 FOREIGN KEY (FK_TLV_JORNADA) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR)
);

