-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TGRADO (
  PK_TGRADO BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  CODIGO VARCHAR(30) NOT NULL,
  NOMBRE VARCHAR(130) NOT NULL,
  FK_TPERIODO_ACADEMICO BIGINT NOT NULL,
  FK_TNIVEL_ENSENANZA BIGINT NOT NULL,
  FK_TLV_GRADO_SIGUIENTE BIGINT,
  TIENE_GRADO_SIGUIENTE bool_sn DEFAULT 'S'  NOT NULL,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT FK_TGRADO_5 CHECK ((TIENE_GRADO_SIGUIENTE = 'S' AND FK_TLV_GRADO_SIGUIENTE IS NOT NULL) OR (TIENE_GRADO_SIGUIENTE = 'N' AND FK_TLV_GRADO_SIGUIENTE IS NULL)),
  CONSTRAINT TGRADO_PK PRIMARY KEY (PK_TGRADO),
  CONSTRAINT U_TGRADO_2 UNIQUE (FK_TPERIODO_ACADEMICO, NOMBRE),
  CONSTRAINT U_TGRADO_1 UNIQUE (FK_TPERIODO_ACADEMICO, CODIGO),
  CONSTRAINT FK_TGRADO_1 FOREIGN KEY (FK_TNIVEL_ENSENANZA) REFERENCES TNIVEL_ENSENANZA (PK_NIVEL_ENSENANZA),
  CONSTRAINT FK_TGRADO_3 FOREIGN KEY (FK_TPERIODO_ACADEMICO) REFERENCES TPERIODO_ACADEMICO (PK_TPERIODO_ACADEMICO),
  CONSTRAINT FK_TGRADO_2 FOREIGN KEY (FK_TLV_GRADO_SIGUIENTE) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR)
);

