  CONSTRAINT FK_TEVAL_DOCENTE_DETALLE_2 FOREIGN KEY (FK_TCOMPETENCIA_GESTION) REFERENCES TCOMPETENCIA_GESTION (PK_TCOMPETENCIA_GESTION)
);

