-- --------------------------------------------------------------------------
--  Tabla: TVALORACION
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TVALORACION (
  PK_TVALORACION BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  CODIGO VARCHAR(30) NOT NULL,
  NOMBRE VARCHAR(130) NOT NULL,
  FK_TVL_TIPO_VALORACION BIGINT NOT NULL,
  GRAFICA_CARITAS VARCHAR(250),
  GRAFICA_SIMBOLO VARCHAR(250),
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT TVALORACION_PK PRIMARY KEY (PK_TVALORACION),
  CONSTRAINT FK_TVALORACION_2 FOREIGN KEY (FK_TVL_TIPO_VALORACION) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR));

--  Indices (2)
CREATE INDEX IF NOT EXISTS IDX_TVALORACION_4 ON TVALORACION (FK_TVL_TIPO_VALORACION) ;
CREATE INDEX IF NOT EXISTS IDX_TVALORACION_ACTIVE ON TVALORACION (PK_TVALORACION) WHERE ACTIVE = true ;

--  Comentarios de columna (4)
COMMENT ON COLUMN TVALORACION.PK_TVALORACION IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TVALORACION.CODIGO IS 'Codigo externo a presentar o identificar el registro al usuario';
COMMENT ON COLUMN TVALORACION.FK_TVL_TIPO_VALORACION IS 'Llave foranea a tabla TVL_TIPO_VALORACION';
COMMENT ON COLUMN TVALORACION.GRAFICA_CARITAS IS 'URL o ruta del grafico de caritas asociado a la valoracion';
COMMENT ON COLUMN TVALORACION.GRAFICA_SIMBOLO IS 'URL o ruta del simbolo grafico asociado a la valoracion';

--  Comentarios de tabla
COMMENT ON TABLE TVALORACION IS 'Catalogo puro de valoraciones institucionales (Bajo, Basico, Alto, Superior, etc.). Su rol dentro de una escala (orden, limites) vive en TESCALA_VALORACION';

-- --------------------------------------------------------------------------
--  Tabla: TESCALA_VALORACION
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TESCALA_VALORACION (
  PK_TESCALA_VALORACION BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TESCALA BIGINT NOT NULL,
  FK_TVALORACION BIGINT NOT NULL,
  FK_TVL_TIPO_VALORACION BIGINT NOT NULL,
  ORDEN NUMERIC(3) NOT NULL,
  LIMITE_INFERIOR NUMERIC(5,2) NOT NULL,
  LIMITE_SUPERIOR NUMERIC(5,2) NOT NULL,
  LIMITE_PROMEDIO NUMERIC(5,2) NOT NULL,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT TESCALA_VALORACION_PK PRIMARY KEY (PK_TESCALA_VALORACION),
  CONSTRAINT U_TESCALA_VALORACION_1 UNIQUE (FK_TESCALA, FK_TVALORACION),
  CONSTRAINT U_TESCALA_VALORACION_2 UNIQUE (FK_TESCALA, FK_TVL_TIPO_VALORACION, ORDEN),
  CONSTRAINT FK_TESCALA_VALORACION_1 FOREIGN KEY (FK_TESCALA) REFERENCES TESCALA (PK_TESCALA) ON DELETE CASCADE,
  CONSTRAINT FK_TESCALA_VALORACION_2 FOREIGN KEY (FK_TVALORACION) REFERENCES TVALORACION (PK_TVALORACION) ON DELETE CASCADE,
  CONSTRAINT FK_TESCALA_VALORACION_3 FOREIGN KEY (FK_TVL_TIPO_VALORACION) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR));

--  Indices (4)
CREATE INDEX IF NOT EXISTS IDX_TESCALA_VALORACION_1 ON TESCALA_VALORACION (FK_TESCALA) ;
CREATE INDEX IF NOT EXISTS IDX_TESCALA_VALORACION_2 ON TESCALA_VALORACION (FK_TVALORACION) ;
CREATE INDEX IF NOT EXISTS IDX_TESCALA_VALORACION_3 ON TESCALA_VALORACION (FK_TVL_TIPO_VALORACION) ;
CREATE INDEX IF NOT EXISTS IDX_TESCALA_VALORACION_ACTIVE ON TESCALA_VALORACION (PK_TESCALA_VALORACION) WHERE ACTIVE = true ;

--  Comentarios de columna (9)
COMMENT ON COLUMN TESCALA_VALORACION.PK_TESCALA_VALORACION IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TESCALA_VALORACION.FK_TESCALA IS 'Llave foranea a tabla TESCALA';
COMMENT ON COLUMN TESCALA_VALORACION.FK_TVALORACION IS 'Llave foranea a tabla TVALORACION';
COMMENT ON COLUMN TESCALA_VALORACION.FK_TVL_TIPO_VALORACION IS 'Tipo de valoracion denormalizado desde TVALORACION para soportar el UNIQUE (FK_TESCALA, FK_TVL_TIPO_VALORACION, ORDEN)';
COMMENT ON COLUMN TESCALA_VALORACION.ORDEN IS 'Posicion de la valoracion dentro de la escala, unica por (escala, tipo de valoracion)';
COMMENT ON COLUMN TESCALA_VALORACION.LIMITE_INFERIOR IS 'Limite inferior del rango numerico de la valoracion dentro de la escala';
COMMENT ON COLUMN TESCALA_VALORACION.LIMITE_SUPERIOR IS 'Limite superior del rango numerico de la valoracion dentro de la escala';
COMMENT ON COLUMN TESCALA_VALORACION.LIMITE_PROMEDIO IS 'Centro del rango (valor tipico) de la valoracion dentro de la escala';

--  Comentarios de tabla
COMMENT ON TABLE TESCALA_VALORACION IS 'Tabla puente muchos-a-muchos entre TESCALA y TVALORACION. Materializa el rol de cada valoracion dentro de cada escala (orden, limites numericos). Permite que una misma valoracion institucional exista en multiples escalas';

