COMMENT ON COLUMN TOBS_SERVICIO_VIVIENDA.FK_TOBSERVADOR IS 'Llave foranea a tabla TOBSERVADOR';
COMMENT ON COLUMN TOBS_SERVICIO_VIVIENDA.FK_TLV_SERVICIO_VIVIENDA IS 'Servicios con los que cuenta la vivienda en donde reside el estudiante. Lista de seleccion multiple *Agua *Energia *Gas *Alcantarillado *Telefono *Internet *Recoleccion de basurasLlave foranea de lista valor para obtener SERVICIO_VIVIENDA';
COMMENT ON COLUMN TOBS_SERVICIO_VIVIENDA.ABANDONOS_TEMPORALES IS 'Contiene la cantidad de veces que el estudiante se ha retirado de la institucion en el a?o academico actual.';

-- --------------------------------------------------------------------------
--  Tabla: TRESERVA_CUPO
--  Manifestacion de interes previa al flujo formal de matricula.
--  Aplicada solo para estudiantes NUEVOS (sin afiliacion previa a la institucion).
--  Realizada por los padres. Fuera de alcance v1 Cartagena
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TRESERVA_CUPO (
  PK_TRESERVA_CUPO BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TUSUARIO BIGINT NOT NULL,
  FK_TESTUDIANTE BIGINT,
  FK_TPADRE BIGINT,
  FK_TLV_PARENTESCO BIGINT NOT NULL,
  ESTADO_CONVIVE_ACUDIENTE bool_sn,
  FK_TGRUPO BIGINT NOT NULL,
  FK_TLV_ESTADO_RESERVA BIGINT NOT NULL,
  FECHA_RESERVA DATE NOT NULL,
  FECHA_VENCIMIENTO DATE NOT NULL,
  OBSERVACIONES VARCHAR(4000),
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TRESERVA_CUPO PRIMARY KEY (PK_TRESERVA_CUPO),
  CONSTRAINT FK_TRESERVA_CUPO_1 FOREIGN KEY (FK_TUSUARIO) REFERENCES TUSUARIO (PK_TUSUARIO),
  CONSTRAINT FK_TRESERVA_CUPO_2 FOREIGN KEY (FK_TESTUDIANTE) REFERENCES TESTUDIANTE (PK_TESTUDIANTE),
  CONSTRAINT FK_TRESERVA_CUPO_3 FOREIGN KEY (FK_TPADRE) REFERENCES TPADRE (PK_TPADRE),
  CONSTRAINT FK_TRESERVA_CUPO_4 FOREIGN KEY (FK_TGRUPO) REFERENCES TGRUPO (PK_TGRUPO),
  CONSTRAINT FK_TRESERVA_CUPO_5 FOREIGN KEY (FK_TLV_ESTADO_RESERVA) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TRESERVA_CUPO_6 FOREIGN KEY (FK_TLV_PARENTESCO) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR)
);

--  Indices (7)
CREATE INDEX IF NOT EXISTS IDX_TRESERVA_CUPO_1 ON TRESERVA_CUPO (FK_TUSUARIO) ;
CREATE INDEX IF NOT EXISTS IDX_TRESERVA_CUPO_2 ON TRESERVA_CUPO (FK_TESTUDIANTE) ;
CREATE INDEX IF NOT EXISTS IDX_TRESERVA_CUPO_3 ON TRESERVA_CUPO (FK_TPADRE) ;
CREATE INDEX IF NOT EXISTS IDX_TRESERVA_CUPO_4 ON TRESERVA_CUPO (FK_TGRUPO) ;
