--  Comentarios de columna (11)
COMMENT ON COLUMN TRESERVA_CUPO.PK_TRESERVA_CUPO IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TRESERVA_CUPO.FK_TUSUARIO IS 'Llave foranea a tabla TUSUARIO (persona del aspirante, NOT NULL: siempre debe existir)';
COMMENT ON COLUMN TRESERVA_CUPO.FK_TESTUDIANTE IS 'Llave foranea a tabla TESTUDIANTE (NULLABLE: solo si el estudiante ya existe en el sistema)';
COMMENT ON COLUMN TRESERVA_CUPO.FK_TPADRE IS 'Llave foranea a tabla TPADRE (NULLABLE: el acudiente puede o no existir previamente)';
COMMENT ON COLUMN TRESERVA_CUPO.FK_TLV_PARENTESCO IS 'Parentesco del acudiente respecto al estudiante (NOT NULL: el form lo pide obligatorio)';
COMMENT ON COLUMN TRESERVA_CUPO.ESTADO_CONVIVE_ACUDIENTE IS 'Indica si el acudiente convive con el estudiante (NULLABLE: el form lo pide obligatorio, se inicializa desde UI)';
COMMENT ON COLUMN TRESERVA_CUPO.FK_TGRUPO IS 'Llave foranea a tabla TGRUPO (sede/jornada/grado al que aspira)';
COMMENT ON COLUMN TRESERVA_CUPO.FK_TLV_ESTADO_RESERVA IS 'Llave foranea de lista valor para obtener ESTADO_RESERVA (VIGENTE / VENCIDA / CONFIRMADA / CANCELADA)';
COMMENT ON COLUMN TRESERVA_CUPO.FECHA_RESERVA IS 'Fecha en que se realizo la reserva del cupo';
COMMENT ON COLUMN TRESERVA_CUPO.FECHA_VENCIMIENTO IS 'Fecha limite de vigencia de la reserva';
COMMENT ON COLUMN TRESERVA_CUPO.OBSERVACIONES IS 'Observaciones adicionales sobre la reserva';

--  Comentarios de tabla
COMMENT ON TABLE TRESERVA_CUPO IS 'Manifestacion de interes previa al flujo formal de matricula (pre-paso para nuevos)';

-- --------------------------------------------------------------------------
--  Tabla: TINSCRIPCION
--  Datos socioeconomicos y de origen del estudiante NUEVO (sin afiliacion previa a la institucion). Realizada despues de la reserva de cupo. Estado tipico: Inscritos.
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TINSCRIPCION (
  PK_TINSCRIPCION BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TESTUDIANTE BIGINT,
  FK_TUSUARIO BIGINT NOT NULL,
  FK_TRESERVA_CUPO BIGINT,
  FK_TLV_ESTADO_INSCRIPCION BIGINT NOT NULL,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,

  CONSTRAINT PK_TINSCRIPCION PRIMARY KEY (PK_TINSCRIPCION),
  CONSTRAINT FK_TINSCRIPCION_1 FOREIGN KEY (FK_TESTUDIANTE) REFERENCES TESTUDIANTE (PK_TESTUDIANTE),
  CONSTRAINT FK_TINSCRIPCION_2 FOREIGN KEY (FK_TUSUARIO) REFERENCES TUSUARIO (PK_TUSUARIO),
  CONSTRAINT FK_TINSCRIPCION_3 FOREIGN KEY (FK_TRESERVA_CUPO) REFERENCES TRESERVA_CUPO (PK_TRESERVA_CUPO),
  CONSTRAINT FK_TINSCRIPCION_4 FOREIGN KEY (FK_TLV_ESTADO_INSCRIPCION) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR)
);

--  Indices (5)
CREATE INDEX IF NOT EXISTS IDX_TINSCRIPCION_1 ON TINSCRIPCION (FK_TESTUDIANTE) ;
CREATE INDEX IF NOT EXISTS IDX_TINSCRIPCION_2 ON TINSCRIPCION (FK_TUSUARIO) ;
CREATE INDEX IF NOT EXISTS IDX_TINSCRIPCION_3 ON TINSCRIPCION (FK_TRESERVA_CUPO) ;
CREATE INDEX IF NOT EXISTS IDX_TINSCRIPCION_4 ON TINSCRIPCION (FK_TLV_ESTADO_INSCRIPCION) ;
CREATE INDEX IF NOT EXISTS IDX_TINSCRIPCION_ACTIVE ON TINSCRIPCION (PK_TINSCRIPCION) WHERE ACTIVE = true ;

--  Comentarios de columna (5)
COMMENT ON COLUMN TINSCRIPCION.PK_TINSCRIPCION IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TINSCRIPCION.FK_TESTUDIANTE IS 'Llave foranea a tabla TESTUDIANTE (opcional: el aspirante nuevo puede no existir aun en el sistema)';
COMMENT ON COLUMN TINSCRIPCION.FK_TUSUARIO IS 'Llave foranea a tabla TUSUARIO (persona del aspirante antes de ser TESTUDIANTE)';
COMMENT ON COLUMN TINSCRIPCION.FK_TRESERVA_CUPO IS 'Llave foranea a tabla TRESERVA_CUPO (NULLABLE: el flujo tipico es reserva -> inscripcion, pero puede haber bypass)';
COMMENT ON COLUMN TINSCRIPCION.FK_TLV_ESTADO_INSCRIPCION IS 'Llave foranea de lista valor para obtener ESTADO_INSCRIPCION (ADMITIDO / RECHAZADO / EN_PROCESO)';

--  Comentarios de tabla
COMMENT ON TABLE TINSCRIPCION IS 'Tabla delgada de trazabilidad del paso de inscripcion (nuevos). Los datos socioeconomicos viven en TMATRICULA';

