  CONSTRAINT FK_TMATRICULA_1 FOREIGN KEY (FK_TESTUDIANTE) REFERENCES TESTUDIANTE (PK_TESTUDIANTE),
  CONSTRAINT FK_TMATRICULA_4 FOREIGN KEY (FK_TGRUPO) REFERENCES TGRUPO (PK_TGRUPO),
  CONSTRAINT FK_TMATRICULA_5 FOREIGN KEY (FK_TLV_ESTADO_MATRICULA) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TMATRICULA_6_TIN FOREIGN KEY (FK_TINSCRIPCION) REFERENCES TINSCRIPCION (PK_TINSCRIPCION),
  CONSTRAINT FK_TMATRICULA_7_PRE FOREIGN KEY (FK_TPREMATRICULA) REFERENCES TPREMATRICULA (PK_TPREMATRICULA),
  CONSTRAINT FK_TMATRICULA_ACUD_PAR FOREIGN KEY (FK_TLV_ACUDIENTE_PARENTESCO) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TMATRICULA_11 FOREIGN KEY (FK_TPADRE) REFERENCES TPADRE (PK_TPADRE),
