  CONSTRAINT FK_TMATRICULA_19 FOREIGN KEY (LISTA_MENSAJE_PROMOCION) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TMATRICULA_12 FOREIGN KEY (FK_TMATRICULA_ANTERIOR) REFERENCES TMATRICULA (PK_TMATRICULA)
);

