CREATE INDEX IF NOT EXISTS IDX_TMATRICULA_3 ON TMATRICULA (FK_ENFASIS) ;
CREATE INDEX IF NOT EXISTS IDX_TMATRICULA_PROMO ON TMATRICULA (PROMOCION_ANTICIPADA) ;
