--  Comentarios de columna (18)
COMMENT ON COLUMN TMATRICULA.PK_TMATRICULA IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TMATRICULA.FK_TESTUDIANTE IS 'Llave foranea a tabla TESTUDIANTE';
COMMENT ON COLUMN TMATRICULA.FK_ENFASIS IS 'Llave foranea a tabla ENFASIS';
COMMENT ON COLUMN TMATRICULA.FK_TGRUPO IS 'Llave foranea a tabla TGRUPO';
COMMENT ON COLUMN TMATRICULA.FK_TLV_ESTADO_MATRICULA IS 'Llave foranea de lista valor para obtener ESTADO_MATRICULA (CURSANDO / APROBADO / REPROBADO / RETIRADO / PROMOVIDO_ANTICIPADO)';
COMMENT ON COLUMN TMATRICULA.FK_TINSCRIPCION IS 'Trazabilidad: si el estudiante fue nuevo, referencia a TINSCRIPCION (NULLABLE)';
COMMENT ON COLUMN TMATRICULA.FK_TPREMATRICULA IS 'Trazabilidad: si el estudiante fue antiguo, referencia a TPREMATRICULA (NULLABLE)';
COMMENT ON COLUMN TMATRICULA.FK_TPADRE IS 'Llave foranea a tabla TPADRE (acudiente definitivo)';
COMMENT ON COLUMN TMATRICULA.FK_TLV_ACUDIENTE_PARENTESCO IS 'Llave foranea de lista valor para obtener ACUDIENTE_PARENTESCO';
COMMENT ON COLUMN TMATRICULA.FK_TLV_SITUACION_ACADEMICA IS 'Llave foranea de lista valor para obtener SITUACION_ACADEMICA';
COMMENT ON COLUMN TMATRICULA.FK_TMATRICULA_ANTERIOR IS 'Cadena de promociones/reinscripciones: apunta a la matricula anterior del estudiante';
COMMENT ON COLUMN TMATRICULA.PROMOCION_ANTICIPADA IS 'Flag derivado: indica si la matricula tiene una promocion asociada en TMATRICULA_PROMOCION (1:1). Verdadero si existe registro TMATRICULA_PROMOCION relacionado';
COMMENT ON COLUMN TMATRICULA.LISTA_MENSAJE_PROMOCION IS 'Mensaje de promocion asociado a la matricula (NOT NULL FK a TLISTA_VALOR categoria MENSAJE_PROMOCION)';
COMMENT ON COLUMN TMATRICULA.ESTUDIANTE_NUEVO IS 'Indica si el estudiante es nuevo en la institucion';
COMMENT ON COLUMN TMATRICULA.ESTUDIANTE_REPITENTE IS 'Indica si el estudiante repite el grado';
COMMENT ON COLUMN TMATRICULA.EDICION_ACUDIENTE IS 'Permite la informacion del acudiente por parte del estudiante';
COMMENT ON COLUMN TMATRICULA.ESTADO_CONVIVE_ACUDIENTE IS 'Indica si el acudiente convive con el estudiante';

--  Comentarios de tabla
COMMENT ON TABLE TMATRICULA IS 'Matricula final consolidada del estudiante activo (punto de convergencia del flujo). Datos socioeconomicos en TMATRICULA_SOCIOECONOMICO (1:1). Promocion (anticipada/retroactiva) y justificacion pedagogica en TMATRICULA_PROMOCION (1:1).';

-- --------------------------------------------------------------------------
--  Tabla: TMATRICULA_SOCIOECONOMICO
--  Datos socioeconomicos del estudiante matriculado. Relacion 1:1 con
--  TMATRICULA via FK_TMATRICULA (UNIQUE). 
--  Contiene: origen del estudiante (sector privado, municipio), institucion
--  de procedencia, condicion de promocion del ano anterior, victima de
--  conflicto, seguridad social (EPS/ARS), subsidios, beneficios y fuente
--  de recursos.
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TMATRICULA_SOCIOECONOMICO (
  PK_TMATRICULA_SOCIOECONOMICO BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TMATRICULA BIGINT NOT NULL,
  PROVIENE_SECTOR_PRIVADO bool_sn,
  PROVIENE_OTRO_MUNICIPIO bool_sn,
  PROVIENE_OTRO_MUNICIPIO_CUAL VARCHAR(150),
  INSTITUCION_ORIGEN VARCHAR(150),
  FK_TLV_TIPO_INSTITUCION_ORIGEN BIGINT,
  FK_TLV_CONDICION_PROMOCION BIGINT,
  FK_TLV_VICTIMA_CONFLICTO BIGINT,
  FK_TMUNICIPIO_VICTIMA BIGINT,
  SEGURIDAD_SOCIAL_ARS VARCHAR(150),
  SEGURIDAD_SOCIAL_EPS VARCHAR(150),
  ESTUDIANTE_SUBSIDIADO bool_sn,
  BENEFICIARIO_CABEZA_FAMILIA bool_sn,
  BEN_HIJO_CABEZA_FAMILIA bool_sn,
  BENEFICIARIO_VETERANO bool_sn,
  BENEFICIARIO_HEROE bool_sn,
  FK_TLV_FUENTE_RECURSO BIGINT,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TMATRICULA_SOCIOECONOMICO PRIMARY KEY (PK_TMATRICULA_SOCIOECONOMICO),
  CONSTRAINT U_TMATRICULA_SOCIOECONOMICO_1 UNIQUE (FK_TMATRICULA) DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT FK_TMAT_SOCIO_1 FOREIGN KEY (FK_TMATRICULA) REFERENCES TMATRICULA (PK_TMATRICULA) ON DELETE CASCADE,
  CONSTRAINT FK_TMAT_SOCIO_2 FOREIGN KEY (FK_TLV_TIPO_INSTITUCION_ORIGEN) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TMAT_SOCIO_3 FOREIGN KEY (FK_TLV_CONDICION_PROMOCION) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TMAT_SOCIO_4 FOREIGN KEY (FK_TLV_VICTIMA_CONFLICTO) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TMAT_SOCIO_5 FOREIGN KEY (FK_TMUNICIPIO_VICTIMA) REFERENCES TMUNICIPIO (PK_TMUNICIPIO),
  CONSTRAINT FK_TMAT_SOCIO_6 FOREIGN KEY (FK_TLV_FUENTE_RECURSO) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR)
);

