CREATE INDEX IF NOT EXISTS IDX_TMAT_SOCIO_1 ON TMATRICULA_SOCIOECONOMICO (FK_TMATRICULA) ;
CREATE INDEX IF NOT EXISTS IDX_TMAT_SOCIO_2 ON TMATRICULA_SOCIOECONOMICO (FK_TLV_TIPO_INSTITUCION_ORIGEN) ;
CREATE INDEX IF NOT EXISTS IDX_TMAT_SOCIO_3 ON TMATRICULA_SOCIOECONOMICO (FK_TLV_CONDICION_PROMOCION) ;
CREATE INDEX IF NOT EXISTS IDX_TMAT_SOCIO_4 ON TMATRICULA_SOCIOECONOMICO (FK_TLV_VICTIMA_CONFLICTO) ;
CREATE INDEX IF NOT EXISTS IDX_TMAT_SOCIO_5 ON TMATRICULA_SOCIOECONOMICO (FK_TMUNICIPIO_VICTIMA) ;
CREATE INDEX IF NOT EXISTS IDX_TMAT_SOCIO_6 ON TMATRICULA_SOCIOECONOMICO (FK_TLV_FUENTE_RECURSO) ;
CREATE INDEX IF NOT EXISTS IDX_TMATRICULA_SOCIOECONOMICO_ACTIVE ON TMATRICULA_SOCIOECONOMICO (PK_TMATRICULA_SOCIOECONOMICO) WHERE ACTIVE = true ;

--  Comentarios de columna (18)
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.PK_TMATRICULA_SOCIOECONOMICO IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.FK_TMATRICULA IS 'Llave foranea a tabla TMATRICULA (UNIQUE: relacion 1:1, snapshot al momento de matricula)';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.PROVIENE_SECTOR_PRIVADO IS 'Indica si el estudiante proviene de sector privado';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.PROVIENE_OTRO_MUNICIPIO IS 'Indica si el estudiante proviene de otro municipio';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.PROVIENE_OTRO_MUNICIPIO_CUAL IS 'Nombre del municipio de origen cuando PROVIENE_OTRO_MUNICIPIO = S';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.INSTITUCION_ORIGEN IS 'Nombre de la institucion educativa de donde proviene';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.FK_TLV_TIPO_INSTITUCION_ORIGEN IS 'Tipo de institucion de origen (incluye No aplica para Instituto de Bienestar)';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.FK_TLV_CONDICION_PROMOCION IS 'Condicion del estudiante al final del ano anterior (Promovido / No promovido)';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.FK_TLV_VICTIMA_CONFLICTO IS 'Indica si el estudiante es victima del conflicto';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.FK_TMUNICIPIO_VICTIMA IS 'Ultimo municipio expulsor (victimas del conflicto)';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.SEGURIDAD_SOCIAL_ARS IS 'Administradora de regimen subsidiado';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.SEGURIDAD_SOCIAL_EPS IS 'Empresa promotora de salud';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.ESTUDIANTE_SUBSIDIADO IS 'Indica si el estudiante es subsidiado';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.BENEFICIARIO_CABEZA_FAMILIA IS 'Indica si es beneficiario como alumno madre cabeza de familia';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.BEN_HIJO_CABEZA_FAMILIA IS 'Indica si es beneficiario como hijo de madre cabeza de familia';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.BENEFICIARIO_VETERANO IS 'Indica si es beneficiario veterano de la fuerza publica';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.BENEFICIARIO_HEROE IS 'Indica si es beneficiario heroe de la nacion';
COMMENT ON COLUMN TMATRICULA_SOCIOECONOMICO.FK_TLV_FUENTE_RECURSO IS 'Fuente de los recursos del estudiante (Familiar / Propio / etc.)';

--  Comentarios de tabla
COMMENT ON TABLE TMATRICULA_SOCIOECONOMICO IS 'Datos socioeconomicos del estudiante (relacion 1:1 con TMATRICULA, snapshot al momento de matricula)';

-- --------------------------------------------------------------------------
--  Tabla: TMATRICULA_PROMOCION
--  Promocion (anticipada o retroactiva) del estudiante y su justificacion pedagogica estructurada.
--  Relacion 1:1 con TMATRICULA via FK_TMATRICULA (UNIQUE).
--  Contiene: grado destino de la promocion, tipo (ANTICIPADA / RETROACTIVA)
--  y los 10 campos de justificacion pedagogica (8 obligatorios + 2 opcionales).
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TMATRICULA_PROMOCION (
  PK_TMATRICULA_PROMOCION BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TMATRICULA BIGINT NOT NULL,
  FK_TGRUPO_PROMOVIDO BIGINT NOT NULL,
  FK_TLV_TIPO_PROMOCION BIGINT NOT NULL,
  JUSTIFICACION_RENDIMIENTO_ACADEMICO VARCHAR(4000) NOT NULL,
  JUSTIFICACION_DESEMPENO_EVALUACIONES VARCHAR(4000) NOT NULL,
  JUSTIFICACION_PENSAMIENTO_CRITICO VARCHAR(4000) NOT NULL,
  JUSTIFICACION_CREATIVIDAD_INNOVACION VARCHAR(4000) NOT NULL,
  JUSTIFICACION_AUTONOMIA_RESPONSABILIDAD VARCHAR(4000) NOT NULL,
  JUSTIFICACION_INTERACCION_SOCIAL VARCHAR(4000) NOT NULL,
  JUSTIFICACION_PROGRESO_INDIVIDUAL VARCHAR(4000) NOT NULL,
  JUSTIFICACION_RETROALIMENTACION VARCHAR(4000) NOT NULL,
  JUSTIFICACION_FACTORES_PERSONALES VARCHAR(4000),
  JUSTIFICACION_INTERVENCIONES_EDUCATIVAS VARCHAR(4000),
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TMATRICULA_PROMOCION PRIMARY KEY (PK_TMATRICULA_PROMOCION),
  CONSTRAINT U_TMATRICULA_PROMOCION_1 UNIQUE (FK_TMATRICULA) DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT FK_TMATRICULA_PROMOCION_1 FOREIGN KEY (FK_TMATRICULA) REFERENCES TMATRICULA (PK_TMATRICULA) ON DELETE CASCADE,
  CONSTRAINT FK_TMATRICULA_PROMOCION_2 FOREIGN KEY (FK_TGRUPO_PROMOVIDO) REFERENCES TGRUPO (PK_TGRUPO),
  CONSTRAINT FK_TMATRICULA_PROMOCION_3 FOREIGN KEY (FK_TLV_TIPO_PROMOCION) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR)
);

--  Indices (4)
CREATE INDEX IF NOT EXISTS IDX_TMATRICULA_PROMOCION_1 ON TMATRICULA_PROMOCION (FK_TMATRICULA) ;
CREATE INDEX IF NOT EXISTS IDX_TMATRICULA_PROMOCION_2 ON TMATRICULA_PROMOCION (FK_TGRUPO_PROMOVIDO) ;
CREATE INDEX IF NOT EXISTS IDX_TMATRICULA_PROMOCION_3 ON TMATRICULA_PROMOCION (FK_TLV_TIPO_PROMOCION) ;
CREATE INDEX IF NOT EXISTS IDX_TMATRICULA_PROMOCION_ACTIVE ON TMATRICULA_PROMOCION (PK_TMATRICULA_PROMOCION) WHERE ACTIVE = true ;

--  Comentarios de columna (17)
COMMENT ON COLUMN TMATRICULA_PROMOCION.PK_TMATRICULA_PROMOCION IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TMATRICULA_PROMOCION.FK_TMATRICULA IS 'Llave foranea a tabla TMATRICULA (UNIQUE: relacion 1:1, snapshot al momento de la promocion)';
COMMENT ON COLUMN TMATRICULA_PROMOCION.FK_TGRUPO_PROMOVIDO IS 'Llave foranea a tabla TGRUPO (grupo destino al que el estudiante es promovido, NOT NULL)';
COMMENT ON COLUMN TMATRICULA_PROMOCION.FK_TLV_TIPO_PROMOCION IS 'Llave foranea de lista valor para obtener TIPO_PROMOCION (ANTICIPADA / RETROACTIVA)';
COMMENT ON COLUMN TMATRICULA_PROMOCION.JUSTIFICACION_RENDIMIENTO_ACADEMICO IS 'Justificacion pedagogica del rendimiento academico del estudiante';
COMMENT ON COLUMN TMATRICULA_PROMOCION.JUSTIFICACION_DESEMPENO_EVALUACIONES IS 'Justificacion pedagogica del desempeno en evaluaciones del estudiante';
COMMENT ON COLUMN TMATRICULA_PROMOCION.JUSTIFICACION_PENSAMIENTO_CRITICO IS 'Justificacion pedagogica de la habilidad de pensamiento critico';
COMMENT ON COLUMN TMATRICULA_PROMOCION.JUSTIFICACION_CREATIVIDAD_INNOVACION IS 'Justificacion pedagogica de creatividad e innovacion';
COMMENT ON COLUMN TMATRICULA_PROMOCION.JUSTIFICACION_AUTONOMIA_RESPONSABILIDAD IS 'Justificacion pedagogica de autonomia y responsabilidad';
COMMENT ON COLUMN TMATRICULA_PROMOCION.JUSTIFICACION_INTERACCION_SOCIAL IS 'Justificacion pedagogica de interaccion social';
COMMENT ON COLUMN TMATRICULA_PROMOCION.JUSTIFICACION_PROGRESO_INDIVIDUAL IS 'Justificacion pedagogica del progreso individual';
COMMENT ON COLUMN TMATRICULA_PROMOCION.JUSTIFICACION_RETROALIMENTACION IS 'Justificacion pedagogica basada en retroalimentacion de profesores y padres';
COMMENT ON COLUMN TMATRICULA_PROMOCION.JUSTIFICACION_FACTORES_PERSONALES IS 'Justificacion pedagogica de factores personales (opcional, NULL permitido)';
COMMENT ON COLUMN TMATRICULA_PROMOCION.JUSTIFICACION_INTERVENCIONES_EDUCATIVAS IS 'Justificacion pedagogica de intervenciones educativas (opcional, NULL permitido)';
COMMENT ON COLUMN TMATRICULA_PROMOCION.CREATED_BY IS 'Usuario que creo el registro';
COMMENT ON COLUMN TMATRICULA_PROMOCION.CREATED_AT IS 'Fecha de creacion del registro';
COMMENT ON COLUMN TMATRICULA_PROMOCION.MODIFIED_BY IS 'Usuario que modifico el registro';
COMMENT ON COLUMN TMATRICULA_PROMOCION.MODIFIED_AT IS 'Fecha de modificacion del registro';

--  Comentarios de tabla
COMMENT ON TABLE TMATRICULA_PROMOCION IS 'Promocion (anticipada o retroactiva) y justificacion pedagogica estructurada del estudiante (relacion 1:1 con TMATRICULA, snapshot al momento de la promocion)';

-- --------------------------------------------------------------------------
--  Tabla: TDIPLOMA
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TDIPLOMA (
  PK_TDIPLOMA BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  LIBRO BIGINT NOT NULL,
  FOLIO BIGINT NOT NULL,
  FK_TPERIODO_ACADEMICO BIGINT NOT NULL,
  FK_TGRUPO BIGINT NOT NULL,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TDIPLOMA PRIMARY KEY (PK_TDIPLOMA),
  CONSTRAINT UK_TDIPLOMA_1 UNIQUE (LIBRO, FOLIO),
  CONSTRAINT FK2_TDIPLOMA FOREIGN KEY (FK_TGRUPO) REFERENCES TGRUPO (PK_TGRUPO),
  CONSTRAINT TDIPLOMA_FK1 FOREIGN KEY (FK_TPERIODO_ACADEMICO) REFERENCES TPERIODO_ACADEMICO (PK_TPERIODO_ACADEMICO)
);

--  Indices (6)
CREATE INDEX IF NOT EXISTS IDX_TDIPLOMA_2 ON TDIPLOMA (LIBRO) ;
CREATE INDEX IF NOT EXISTS IDX_TDIPLOMA_3 ON TDIPLOMA (FOLIO) ;
CREATE INDEX IF NOT EXISTS IDX_TDIPLOMA_4 ON TDIPLOMA (FK_TPERIODO_ACADEMICO) ;
CREATE INDEX IF NOT EXISTS IDX_TDIPLOMA_5 ON TDIPLOMA (FK_TGRUPO) ;
CREATE INDEX IF NOT EXISTS IDX_TDIPLOMA_ACTIVE ON TDIPLOMA (PK_TDIPLOMA) WHERE ACTIVE = true ;

--  Comentarios de columna (5)
COMMENT ON COLUMN TDIPLOMA.PK_TDIPLOMA IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TDIPLOMA.FK_TPERIODO_ACADEMICO IS 'Llave foranea a tabla TPERIODO_ACADEMICO';
COMMENT ON COLUMN TDIPLOMA.FK_TGRUPO IS 'Llave foranea a tabla TGRUPO';

-- --------------------------------------------------------------------------
--  Tabla: TTRASLADO_ESTUDIANTE
--  Refactorizacion: se elimina el campo APROBADO y se reemplaza por
--  FK_TLV_ESTADO_TRASLADO (SOLICITADO / EN_TRANSITO / CAPTURADO / CANCELADO).
--  El estudiante solo debe estar 'Retirado' en su sede de origen para ser
--  capturado por la nueva sede (sin aprobacion entre colegios).
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TTRASLADO_ESTUDIANTE (
  PK_TTRASLADO_ESTUDIANTE BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  MOTIVO VARCHAR(4000) NOT NULL,
  FK_TLV_ESTADO_TRASLADO BIGINT NOT NULL,
  FK_TGRUPO_ORIGEN BIGINT NOT NULL,
  FK_TGRUPO_DESTINO BIGINT NOT NULL,
  FK_TESTUDIANTE BIGINT NOT NULL,
  FK_TFUNCIONARIO BIGINT,
  FECHA_SOLICITUD DATE DEFAULT CURRENT_DATE NOT NULL,
  FECHA_CAPTURA DATE,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TTRASLADO_ESTUDIANTE PRIMARY KEY (PK_TTRASLADO_ESTUDIANTE),
  CONSTRAINT FK_TTRASLADO_ESTUDIANTE_1 FOREIGN KEY (FK_TGRUPO_ORIGEN) REFERENCES TGRUPO (PK_TGRUPO) ON DELETE CASCADE,
  CONSTRAINT FK_TTRASLADO_ESTUDIANTE_2 FOREIGN KEY (FK_TGRUPO_DESTINO) REFERENCES TGRUPO (PK_TGRUPO) ON DELETE CASCADE,
  CONSTRAINT FK_TTRASLADO_ESTUDIANTE_3 FOREIGN KEY (FK_TESTUDIANTE) REFERENCES TESTUDIANTE (PK_TESTUDIANTE) ON DELETE CASCADE,
  CONSTRAINT FK_TTRASLADO_ESTUDIANTE_4 FOREIGN KEY (FK_TFUNCIONARIO) REFERENCES TFUNCIONARIO (PK_TFUNCIONARIO) ON DELETE SET NULL,
  CONSTRAINT FK_TTRASLADO_ESTUDIANTE_5 FOREIGN KEY (FK_TLV_ESTADO_TRASLADO) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR)
);

--  Indices (7)
CREATE INDEX IF NOT EXISTS IDX_TTRASLADO_ESTUDIANTE_4 ON TTRASLADO_ESTUDIANTE (FK_TGRUPO_ORIGEN) ;
CREATE INDEX IF NOT EXISTS IDX_TTRASLADO_ESTUDIANTE_5 ON TTRASLADO_ESTUDIANTE (FK_TGRUPO_DESTINO) ;
CREATE INDEX IF NOT EXISTS IDX_TTRASLADO_ESTUDIANTE_6 ON TTRASLADO_ESTUDIANTE (FK_TESTUDIANTE) ;
CREATE INDEX IF NOT EXISTS IDX_TTRASLADO_ESTUDIANTE_7 ON TTRASLADO_ESTUDIANTE (FK_TFUNCIONARIO) ;
CREATE INDEX IF NOT EXISTS IDX_TTRASLADO_ESTUDIANTE_8 ON TTRASLADO_ESTUDIANTE (FECHA_SOLICITUD) ;
CREATE INDEX IF NOT EXISTS IDX_TTRASLADO_ESTUDIANTE_9 ON TTRASLADO_ESTUDIANTE (FK_TLV_ESTADO_TRASLADO) ;
CREATE INDEX IF NOT EXISTS IDX_TTRASLADO_ESTUDIANTE_ACTIVE ON TTRASLADO_ESTUDIANTE (PK_TTRASLADO_ESTUDIANTE) WHERE ACTIVE = true ;

--  Comentarios de columna (10)
COMMENT ON COLUMN TTRASLADO_ESTUDIANTE.PK_TTRASLADO_ESTUDIANTE IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TTRASLADO_ESTUDIANTE.MOTIVO IS 'Motivo del traslado';
COMMENT ON COLUMN TTRASLADO_ESTUDIANTE.FK_TLV_ESTADO_TRASLADO IS 'Llave foranea de lista valor para obtener ESTADO_TRASLADO (SOLICITADO / EN_TRANSITO / CAPTURADO / CANCELADO)';
COMMENT ON COLUMN TTRASLADO_ESTUDIANTE.FK_TGRUPO_ORIGEN IS 'Llave foranea a tabla TGRUPO (sede de origen)';
COMMENT ON COLUMN TTRASLADO_ESTUDIANTE.FK_TGRUPO_DESTINO IS 'Llave foranea a tabla TGRUPO (sede de destino)';
COMMENT ON COLUMN TTRASLADO_ESTUDIANTE.FK_TESTUDIANTE IS 'Llave foranea a tabla TESTUDIANTE';
COMMENT ON COLUMN TTRASLADO_ESTUDIANTE.FK_TFUNCIONARIO IS 'Llave foranea a tabla TFUNCIONARIO (quien registro/autorizo el traslado)';
COMMENT ON COLUMN TTRASLADO_ESTUDIANTE.FECHA_SOLICITUD IS 'Fecha en que se solicito el traslado';
COMMENT ON COLUMN TTRASLADO_ESTUDIANTE.FECHA_CAPTURA IS 'Fecha en que la sede destino capturo al estudiante';

--  Comentarios de tabla
COMMENT ON TABLE TTRASLADO_ESTUDIANTE IS 'Tabla de control de traslados de los estudiantes (sin aprobacion entre colegios)';

-- --------------------------------------------------------------------------
--  Tabla: TTRASLADO_MATRICULA
--  Tabla puente que conecta TTRASLADO_ESTUDIANTE con TMATRICULA.
--  Modelada como relacion M:N estructural, pero por convencion cada
--  matricula tiene exactamente un origen (FK_TINSCRIPCION / FK_TPREMATRICULA
--  / fila en TTRASLADO_MATRICULA); la invariante se valida en la capa
--  de aplicacion. Permite registrar cuando un estudiante trasladado
--  (capturado por la sede destino) genera una matricula oficial.
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TTRASLADO_MATRICULA (
  PK_TTRASLADO_MATRICULA BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TMATRICULA BIGINT NOT NULL,
  FK_TTRASLADO_ESTUDIANTE BIGINT NOT NULL,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TTRASLADO_MATRICULA PRIMARY KEY (PK_TTRASLADO_MATRICULA),
  CONSTRAINT FK_TTRASLADO_MATRICULA_1 FOREIGN KEY (FK_TMATRICULA) REFERENCES TMATRICULA (PK_TMATRICULA) ON DELETE CASCADE,
  CONSTRAINT FK_TTRASLADO_MATRICULA_2 FOREIGN KEY (FK_TTRASLADO_ESTUDIANTE) REFERENCES TTRASLADO_ESTUDIANTE (PK_TTRASLADO_ESTUDIANTE) ON DELETE CASCADE
);

--  Indices (3)
CREATE INDEX IF NOT EXISTS IDX_TTRASLADO_MATRICULA_1 ON TTRASLADO_MATRICULA (FK_TMATRICULA) ;
CREATE INDEX IF NOT EXISTS IDX_TTRASLADO_MATRICULA_2 ON TTRASLADO_MATRICULA (FK_TTRASLADO_ESTUDIANTE) ;
CREATE INDEX IF NOT EXISTS IDX_TTRASLADO_MATRICULA_ACTIVE ON TTRASLADO_MATRICULA (PK_TTRASLADO_MATRICULA) WHERE ACTIVE = true ;

--  Comentarios de columna (5)
COMMENT ON COLUMN TTRASLADO_MATRICULA.PK_TTRASLADO_MATRICULA IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TTRASLADO_MATRICULA.FK_TMATRICULA IS 'Llave foranea a tabla TMATRICULA (matricula oficial resultante del traslado capturado)';
COMMENT ON COLUMN TTRASLADO_MATRICULA.FK_TTRASLADO_ESTUDIANTE IS 'Llave foranea a tabla TTRASLADO_ESTUDIANTE (origen del estudiante trasladado)';
COMMENT ON COLUMN TTRASLADO_MATRICULA.CREATED_BY IS 'Usuario que creo el registro';
COMMENT ON COLUMN TTRASLADO_MATRICULA.CREATED_AT IS 'Fecha de creacion del registro';

--  Comentarios de tabla
COMMENT ON TABLE TTRASLADO_MATRICULA IS 'Tabla puente entre TTRASLADO_ESTUDIANTE y TMATRICULA. Por convencion cada matricula tiene exactamente un origen (TINSCRIPCION / TPREMATRICULA / fila en TTRASLADO_MATRICULA); la regla se valida en la aplicacion.';

-- --------------------------------------------------------------------------
--  Tabla: TUNIDAD
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TUNIDAD (
  PK_TUNIDAD BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  NOMBRE VARCHAR(250) NOT NULL,
  FK_TASIGNATURA BIGINT NOT NULL,
  FK_TGRADO BIGINT NOT NULL,
  FK_TPERIODO_EVALUACION BIGINT NOT NULL,
  FK_TFUNCIONARIO BIGINT NOT NULL,
  DESCRIPCION VARCHAR(4000),
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TUNIDAD PRIMARY KEY (PK_TUNIDAD),
  CONSTRAINT UN_TUNIDAD_1 UNIQUE (NOMBRE, FK_TASIGNATURA, FK_TGRADO, FK_TPERIODO_EVALUACION) DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT FK_TUNIDAD_1 FOREIGN KEY (FK_TASIGNATURA) REFERENCES TASIGNATURA (PK_TASIGNATURA) ON DELETE CASCADE,
  CONSTRAINT FK_TUNIDAD_2 FOREIGN KEY (FK_TGRADO) REFERENCES TGRADO (PK_TGRADO) ON DELETE CASCADE,
  CONSTRAINT FK_TUNIDAD_3 FOREIGN KEY (FK_TPERIODO_EVALUACION) REFERENCES TPERIODO_EVALUACION (PK_TPERIODO_EVALUACION),
  CONSTRAINT FK_TUNIDAD_4 FOREIGN KEY (FK_TFUNCIONARIO) REFERENCES TFUNCIONARIO (PK_TFUNCIONARIO) ON DELETE SET NULL
);

--  Indices (5)
CREATE INDEX IF NOT EXISTS IDX_TUNIDAD_1 ON TUNIDAD (FK_TGRADO) ;
CREATE INDEX IF NOT EXISTS IDX_TUNIDAD_2 ON TUNIDAD (FK_TASIGNATURA) ;
CREATE INDEX IF NOT EXISTS IDX_TUNIDAD_3 ON TUNIDAD (FK_TPERIODO_EVALUACION) ;
CREATE INDEX IF NOT EXISTS IDX_TUNIDAD_4 ON TUNIDAD (FK_TFUNCIONARIO) ;
CREATE INDEX IF NOT EXISTS IDX_TUNIDAD_ACTIVE ON TUNIDAD (PK_TUNIDAD) WHERE ACTIVE = true ;

--  Comentarios de columna (6)
COMMENT ON COLUMN TUNIDAD.PK_TUNIDAD IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TUNIDAD.NOMBRE IS 'Nombre de la unidad pedagogica (ej: Unidad 1)';
COMMENT ON COLUMN TUNIDAD.FK_TASIGNATURA IS 'Llave foranea a tabla TASIGNATURA';
COMMENT ON COLUMN TUNIDAD.FK_TGRADO IS 'Llave foranea a tabla TGRADO';
COMMENT ON COLUMN TUNIDAD.FK_TPERIODO_EVALUACION IS 'Llave foranea a tabla TPERIODO_EVALUACION';
COMMENT ON COLUMN TUNIDAD.FK_TFUNCIONARIO IS 'Docente autor de la unidad. Llave foranea a tabla TFUNCIONARIO';
COMMENT ON COLUMN TUNIDAD.DESCRIPCION IS 'Descripcion de la unidad pedagogica';

--  Comentario de tabla
COMMENT ON TABLE TUNIDAD IS 'Contenedor pedagogico que agrupa actividades por asignatura, grupo y periodo de evaluacion';

-- --------------------------------------------------------------------------
--  Tabla: TUNIDAD_CONTENIDO
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TUNIDAD_CONTENIDO (
  PK_TUNIDAD_CONTENIDO BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TUNIDAD BIGINT NOT NULL,
  ORDEN NUMERIC(4) NOT NULL,
  DESCRIPCION VARCHAR(4000) NOT NULL,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TUNIDAD_CONTENIDO PRIMARY KEY (PK_TUNIDAD_CONTENIDO),
  CONSTRAINT FK_TUNIDAD_CONTENIDO_1 FOREIGN KEY (FK_TUNIDAD) REFERENCES TUNIDAD (PK_TUNIDAD) ON DELETE CASCADE
);

--  Indices (3)
CREATE INDEX IF NOT EXISTS IDX_TUNIDAD_CONTENIDO_1 ON TUNIDAD_CONTENIDO (FK_TUNIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TUNIDAD_CONTENIDO_2 ON TUNIDAD_CONTENIDO (FK_TUNIDAD, ORDEN) ;
CREATE INDEX IF NOT EXISTS IDX_TUNIDAD_CONTENIDO_ACTIVE ON TUNIDAD_CONTENIDO (PK_TUNIDAD_CONTENIDO) WHERE ACTIVE = true ;

--  Comentarios de columna (4)
COMMENT ON COLUMN TUNIDAD_CONTENIDO.PK_TUNIDAD_CONTENIDO IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TUNIDAD_CONTENIDO.FK_TUNIDAD IS 'Llave foranea a tabla TUNIDAD';
COMMENT ON COLUMN TUNIDAD_CONTENIDO.ORDEN IS 'Posicion del criterio en la lista (1, 2, 3...)';
COMMENT ON COLUMN TUNIDAD_CONTENIDO.DESCRIPCION IS 'Texto del criterio de contenido';

--  Comentario de tabla
COMMENT ON TABLE TUNIDAD_CONTENIDO IS 'Criterios de contenido de una unidad pedagogica (uno por registro, ordenados)';

-- --------------------------------------------------------------------------
--  Tabla: TUNIDAD_OBJETIVO
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TUNIDAD_OBJETIVO (
  PK_TUNIDAD_OBJETIVO BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TUNIDAD BIGINT NOT NULL,
  ORDEN NUMERIC(4) NOT NULL,
  DESCRIPCION VARCHAR(4000) NOT NULL,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TUNIDAD_OBJETIVO PRIMARY KEY (PK_TUNIDAD_OBJETIVO),
  CONSTRAINT FK_TUNIDAD_OBJETIVO_1 FOREIGN KEY (FK_TUNIDAD) REFERENCES TUNIDAD (PK_TUNIDAD) ON DELETE CASCADE
);

--  Indices (3)
CREATE INDEX IF NOT EXISTS IDX_TUNIDAD_OBJETIVO_1 ON TUNIDAD_OBJETIVO (FK_TUNIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TUNIDAD_OBJETIVO_2 ON TUNIDAD_OBJETIVO (FK_TUNIDAD, ORDEN) ;
CREATE INDEX IF NOT EXISTS IDX_TUNIDAD_OBJETIVO_ACTIVE ON TUNIDAD_OBJETIVO (PK_TUNIDAD_OBJETIVO) WHERE ACTIVE = true ;

--  Comentarios de columna (4)
COMMENT ON COLUMN TUNIDAD_OBJETIVO.PK_TUNIDAD_OBJETIVO IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TUNIDAD_OBJETIVO.FK_TUNIDAD IS 'Llave foranea a tabla TUNIDAD';
COMMENT ON COLUMN TUNIDAD_OBJETIVO.ORDEN IS 'Posicion del objetivo en la lista (1, 2, 3...)';
COMMENT ON COLUMN TUNIDAD_OBJETIVO.DESCRIPCION IS 'Texto del objetivo de la unidad';

--  Comentario de tabla
COMMENT ON TABLE TUNIDAD_OBJETIVO IS 'Objetivos pedagogicos de una unidad (uno por registro, ordenados)';

-- --------------------------------------------------------------------------
--  Tabla: TACTIVIDAD
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TACTIVIDAD (
  PK_TACTIVIDAD BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TUNIDAD BIGINT NOT NULL,
  TITULO VARCHAR(250) NOT NULL,
  DESCRIPCION VARCHAR(4000),
  FECHA_CREACION DATE NOT NULL,
  INFLUENCIA NUMERIC(3),
  NOTA_MAXIMA NUMERIC(3),
  FK_TACTIVIDAD BIGINT,
  FK_TGRUPO BIGINT,
  FK_TLV_TIPO_ACTIVIDAD BIGINT NOT NULL,
  FK_TLV_TIPO_CALCULO BIGINT,
  FK_TLV_JERARQUIA BIGINT NOT NULL,
  -- Programacion
  FECHA_INICIO DATE,
  FECHA_CIERRE DATE,
  DURACION_ESTIMADA NUMERIC(5,2),
  SEMANA_CRONOGRAMA VARCHAR(50),
  FK_TLV_MODALIDAD BIGINT,
  -- Materiales (lista breve - texto)
  MATERIAL_REQUERIDO VARCHAR(4000),
  -- Evaluacion
  ES_EVALUATIVA bool_sn DEFAULT 'S',
  ES_RECUPERACION bool_sn DEFAULT 'N',
  FK_TLV_INSTRUMENTO_EVALUACION BIGINT,
  DESCRIPCION_INSTRUMENTO VARCHAR(4000),
  FK_TLV_TIPO_EVIDENCIA BIGINT,
  FK_TLV_METODO_VALORACION BIGINT,
  REQUIERE_ARCHIVO bool_sn DEFAULT 'N',
  REQUIERE_TEXTO bool_sn DEFAULT 'N',
  -- Seguimiento
  GENERA_EVIDENCIAS bool_sn DEFAULT 'N',
  REQUIERE_VALIDACION_COORDINADOR bool_sn DEFAULT 'N',
  OBSERVACIONES_DOCENTE VARCHAR(4000),
  -- Auditoria / control
  FECHA_CALIFICADO DATE,
  FECHA_PUBLICACION DATE,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TACTIVIDAD PRIMARY KEY (PK_TACTIVIDAD),
  CONSTRAINT U_TACTIVIDAD_1 UNIQUE (TITULO, FK_TUNIDAD, FK_TGRUPO, FK_TLV_JERARQUIA) DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT FK_TACTIVIDAD_3 FOREIGN KEY (FK_TGRUPO) REFERENCES TGRUPO (PK_TGRUPO) ON DELETE CASCADE,
  CONSTRAINT FK_TACTIVIDAD_5 FOREIGN KEY (FK_TLV_TIPO_ACTIVIDAD) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TACTIVIDAD_6 FOREIGN KEY (FK_TLV_TIPO_CALCULO) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TACTIVIDAD_7 FOREIGN KEY (FK_TLV_JERARQUIA) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TACTIVIDAD_1 FOREIGN KEY (FK_TACTIVIDAD) REFERENCES TACTIVIDAD (PK_TACTIVIDAD),
  CONSTRAINT FK_TACTIVIDAD_9 FOREIGN KEY (FK_TUNIDAD) REFERENCES TUNIDAD (PK_TUNIDAD) ON DELETE CASCADE,
  CONSTRAINT FK_TACTIVIDAD_10 FOREIGN KEY (FK_TLV_MODALIDAD) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TACTIVIDAD_11 FOREIGN KEY (FK_TLV_INSTRUMENTO_EVALUACION) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TACTIVIDAD_12_TE FOREIGN KEY (FK_TLV_TIPO_EVIDENCIA) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TACTIVIDAD_13_MV FOREIGN KEY (FK_TLV_METODO_VALORACION) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR)
);

--  Indices (16)
CREATE INDEX IF NOT EXISTS I_TACTIVIDAD_1 ON TACTIVIDAD (FK_TGRUPO) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_15 ON TACTIVIDAD (FECHA_CALIFICADO) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_16 ON TACTIVIDAD (FECHA_PUBLICACION) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_4 ON TACTIVIDAD (FECHA_CREACION) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_7 ON TACTIVIDAD (FK_TACTIVIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_12 ON TACTIVIDAD (FK_TLV_TIPO_ACTIVIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_13 ON TACTIVIDAD (FK_TLV_TIPO_CALCULO) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_14 ON TACTIVIDAD (FK_TLV_JERARQUIA) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_20 ON TACTIVIDAD (FK_TUNIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_21 ON TACTIVIDAD (FECHA_INICIO) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_22 ON TACTIVIDAD (FECHA_CIERRE) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_23 ON TACTIVIDAD (FK_TLV_MODALIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_24 ON TACTIVIDAD (FK_TLV_INSTRUMENTO_EVALUACION) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_25 ON TACTIVIDAD (FK_TLV_TIPO_EVIDENCIA) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_ACTIVE ON TACTIVIDAD (PK_TACTIVIDAD) WHERE ACTIVE = true ;

--  Comentarios de columna (25)
COMMENT ON COLUMN TACTIVIDAD.PK_TACTIVIDAD IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TACTIVIDAD.INFLUENCIA IS 'Contiene el peso porcentual de la actividad.';
COMMENT ON COLUMN TACTIVIDAD.NOTA_MAXIMA IS 'Define la nota maxima que se podra calificar al estudiante si el tipo de calculo definido es SUMATORIA';
COMMENT ON COLUMN TACTIVIDAD.FK_TACTIVIDAD IS 'Llave foranea a tabla TACTIVIDAD';
COMMENT ON COLUMN TACTIVIDAD.FK_TGRUPO IS 'Llave foranea a tabla TGRUPO';
COMMENT ON COLUMN TACTIVIDAD.FK_TLV_TIPO_ACTIVIDAD IS 'Contiene tipo al que pertenece la actividad. Este dato de entrada solo sera habilitado si el dato de entrada Jerarquia tiene como valor 1 - Actividad. En caso de que el dato de entrada Jerarquia tenga como valor 2 - Criterio el valor por defecto es de este dato de entrada es Otro Llave foranea de lista valor para obtener TIPO_ACTIVIDAD';
COMMENT ON COLUMN TACTIVIDAD.FK_TLV_TIPO_CALCULO IS 'Define que tipo de operacion se debe realizar para obtener la nota definitiva de la actividad. Este dato de entrada solo sera habilitado si el dato de entrada Jerarquia tiene como valor 2 - Criterio. Llave foranea de lista valor para obtener TIPO_CALCULO';
COMMENT ON COLUMN TACTIVIDAD.FK_TLV_JERARQUIA IS 'Lista de Valor JERARQUIA_ACTIVIDADLlave foranea de lista valor para obtener JERARQUIA';
COMMENT ON COLUMN TACTIVIDAD.FK_TUNIDAD IS 'Llave foranea a tabla TUNIDAD. Toda actividad debe pertenecer a una unidad pedagogica.';
COMMENT ON COLUMN TACTIVIDAD.FECHA_INICIO IS 'Fecha de inicio de la actividad (programacion)';
COMMENT ON COLUMN TACTIVIDAD.FECHA_CIERRE IS 'Fecha de entrega o cierre de la actividad (programacion)';
COMMENT ON COLUMN TACTIVIDAD.DURACION_ESTIMADA IS 'Duracion estimada en horas o sesiones (programacion)';
COMMENT ON COLUMN TACTIVIDAD.SEMANA_CRONOGRAMA IS 'Semana del cronograma a la que pertenece la actividad (ej: Semana 10-12)';
COMMENT ON COLUMN TACTIVIDAD.FK_TLV_MODALIDAD IS 'Modalidad de la actividad. Llave foranea de lista valor para obtener MODALIDAD. Valores: Presencial, Virtual, Mixta';
COMMENT ON COLUMN TACTIVIDAD.MATERIAL_REQUERIDO IS 'Lista breve en texto de materiales requeridos (resumen). Para detalle usar TACTIVIDAD_MATERIAL';
COMMENT ON COLUMN TACTIVIDAD.ES_EVALUATIVA IS 'Indica si la actividad es evaluativa (S/N). CHECK IN (S,N)';
COMMENT ON COLUMN TACTIVIDAD.ES_RECUPERACION IS 'Indica si la actividad es una recuperacion de otra actividad o de la nota final (S/N). CHECK IN (S,N). Si S, debe existir su registro en TACTIVIDAD_RECUPERACION con la configuracion del destino y la forma de calculo';
COMMENT ON COLUMN TACTIVIDAD.FK_TLV_INSTRUMENTO_EVALUACION IS 'Instrumento de evaluacion. Llave foranea de lista valor para obtener INSTRUMENTO_EVALUACION. Valores: Rubrica, Lista de cotejo, Escala de valoracion, Otro';
COMMENT ON COLUMN TACTIVIDAD.DESCRIPCION_INSTRUMENTO IS 'Descripcion del instrumento de evaluacion aplicado';
COMMENT ON COLUMN TACTIVIDAD.FK_TLV_TIPO_EVIDENCIA IS 'Tipo de evidencia esperada. Llave foranea de lista valor para obtener TIPO_EVIDENCIA';
COMMENT ON COLUMN TACTIVIDAD.FK_TLV_METODO_VALORACION IS 'Metodo de valoracion. Llave foranea de lista valor para obtener METODO_VALORACION';
COMMENT ON COLUMN TACTIVIDAD.REQUIERE_ARCHIVO IS 'Indica si el estudiante debe adjuntar un archivo (S/N). CHECK IN (S,N)';
COMMENT ON COLUMN TACTIVIDAD.REQUIERE_TEXTO IS 'Indica si el estudiante debe escribir una respuesta en texto (S/N). CHECK IN (S,N)';
COMMENT ON COLUMN TACTIVIDAD.GENERA_EVIDENCIAS IS 'Indica si la actividad genera evidencias para el observador (S/N). CHECK IN (S,N)';
COMMENT ON COLUMN TACTIVIDAD.REQUIERE_VALIDACION_COORDINADOR IS 'Indica si requiere validacion del coordinador (S/N). CHECK IN (S,N)';
COMMENT ON COLUMN TACTIVIDAD.OBSERVACIONES_DOCENTE IS 'Observaciones generales del docente sobre la actividad';

-- --------------------------------------------------------------------------
--  Tabla: TACTIVIDAD_ESTUDIANTE
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TACTIVIDAD_ESTUDIANTE (
  PK_TACTIVIDAD_ESTUDIANTE BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TACTIVIDAD BIGINT NOT NULL,
  FK_TMATRICULA BIGINT NOT NULL,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TACTIVIDAD_ESTUDIANTE PRIMARY KEY (PK_TACTIVIDAD_ESTUDIANTE),
  CONSTRAINT UN_TACTIVIDAD_ESTUDIANTE_1 UNIQUE (FK_TACTIVIDAD, FK_TMATRICULA) DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT FK_TACTIVIDAD_ESTUDIANTE_1 FOREIGN KEY (FK_TACTIVIDAD) REFERENCES TACTIVIDAD (PK_TACTIVIDAD) ON DELETE CASCADE,
  CONSTRAINT FK_TACTIVIDAD_ESTUDIANTE_2 FOREIGN KEY (FK_TMATRICULA) REFERENCES TMATRICULA (PK_TMATRICULA) ON DELETE CASCADE
);

--  Indices (3)
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_ESTUDIANTE_1 ON TACTIVIDAD_ESTUDIANTE (FK_TACTIVIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_ESTUDIANTE_2 ON TACTIVIDAD_ESTUDIANTE (FK_TMATRICULA) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_ESTUDIANTE_ACTIVE ON TACTIVIDAD_ESTUDIANTE (PK_TACTIVIDAD_ESTUDIANTE) WHERE ACTIVE = true ;

--  Comentarios de columna (3)
COMMENT ON COLUMN TACTIVIDAD_ESTUDIANTE.PK_TACTIVIDAD_ESTUDIANTE IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TACTIVIDAD_ESTUDIANTE.FK_TACTIVIDAD IS 'Llave foranea a tabla TACTIVIDAD';
COMMENT ON COLUMN TACTIVIDAD_ESTUDIANTE.FK_TMATRICULA IS 'Llave foranea a tabla TMATRICULA (matricula del estudiante)';

--  Comentario de tabla
COMMENT ON TABLE TACTIVIDAD_ESTUDIANTE IS 'Pivote N:M entre TACTIVIDAD y TMATRICULA. Permite asignar una actividad a estudiantes especificos de un grupo';

-- --------------------------------------------------------------------------
--  Tabla: TACTIVIDAD_MATERIAL
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TACTIVIDAD_MATERIAL (
  PK_TACTIVIDAD_MATERIAL BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TACTIVIDAD BIGINT NOT NULL,
  ORDEN NUMERIC(4) NOT NULL,
  FK_TLV_TIPO_RECURSO BIGINT NOT NULL,
  URL VARCHAR(4000),
  FK_TARCHIVO BIGINT,
  DESCRIPCION VARCHAR(4000),
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TACTIVIDAD_MATERIAL PRIMARY KEY (PK_TACTIVIDAD_MATERIAL),
  CONSTRAINT CK_TACTIVIDAD_MATERIAL_RECURSO CHECK (
    (URL IS NOT NULL AND FK_TARCHIVO IS NULL) OR
    (URL IS NULL AND FK_TARCHIVO IS NOT NULL)
  ),
  CONSTRAINT FK_TACTIVIDAD_MATERIAL_1 FOREIGN KEY (FK_TACTIVIDAD) REFERENCES TACTIVIDAD (PK_TACTIVIDAD) ON DELETE CASCADE,
  CONSTRAINT FK_TACTIVIDAD_MATERIAL_2 FOREIGN KEY (FK_TLV_TIPO_RECURSO) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TACTIVIDAD_MATERIAL_3 FOREIGN KEY (FK_TARCHIVO) REFERENCES TARCHIVO (PK_TARCHIVO)
);

--  Indices (5)
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_MATERIAL_1 ON TACTIVIDAD_MATERIAL (FK_TACTIVIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_MATERIAL_2 ON TACTIVIDAD_MATERIAL (FK_TACTIVIDAD, ORDEN) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_MATERIAL_3 ON TACTIVIDAD_MATERIAL (FK_TLV_TIPO_RECURSO) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_MATERIAL_4 ON TACTIVIDAD_MATERIAL (FK_TARCHIVO) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_MATERIAL_ACTIVE ON TACTIVIDAD_MATERIAL (PK_TACTIVIDAD_MATERIAL) WHERE ACTIVE = true ;

--  Comentarios de columna (7)
COMMENT ON COLUMN TACTIVIDAD_MATERIAL.PK_TACTIVIDAD_MATERIAL IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TACTIVIDAD_MATERIAL.FK_TACTIVIDAD IS 'Llave foranea a tabla TACTIVIDAD';
COMMENT ON COLUMN TACTIVIDAD_MATERIAL.ORDEN IS 'Posicion del recurso en la lista (1, 2, 3...)';
COMMENT ON COLUMN TACTIVIDAD_MATERIAL.FK_TLV_TIPO_RECURSO IS 'Tipo de recurso. Llave foranea de lista valor para obtener TIPO_RECURSO. Valores: URL, ARCHIVO';
COMMENT ON COLUMN TACTIVIDAD_MATERIAL.URL IS 'URL del recurso externo (cuando FK_TLV_TIPO_RECURSO = URL)';
COMMENT ON COLUMN TACTIVIDAD_MATERIAL.FK_TARCHIVO IS 'Llave foranea a tabla TARCHIVO (cuando FK_TLV_TIPO_RECURSO = ARCHIVO)';
COMMENT ON COLUMN TACTIVIDAD_MATERIAL.DESCRIPCION IS 'Descripcion o nota del recurso';

--  Comentario de tabla
COMMENT ON TABLE TACTIVIDAD_MATERIAL IS 'Recursos requeridos para una actividad: URL externa o archivo (uno por registro, ordenados). CHECK garantiza que solo uno de URL/FK_TARCHIVO este lleno';

-- --------------------------------------------------------------------------
--  Tabla: TACTIVIDAD_RUBRICA_CRITERIO
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TACTIVIDAD_RUBRICA_CRITERIO (
