  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TAC_RUBRICA_CRITERIO PRIMARY KEY (PK_TACTIVIDAD_RUBRICA_CRITERIO),
  CONSTRAINT FK_TAC_RUBRICA_CRITERIO_1 FOREIGN KEY (FK_TACTIVIDAD) REFERENCES TACTIVIDAD (PK_TACTIVIDAD) ON DELETE CASCADE
);

--  Indices (3)
CREATE INDEX IF NOT EXISTS IDX_TAC_RUBRICA_CRITERIO_1 ON TACTIVIDAD_RUBRICA_CRITERIO (FK_TACTIVIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TAC_RUBRICA_CRITERIO_2 ON TACTIVIDAD_RUBRICA_CRITERIO (FK_TACTIVIDAD, ORDEN) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_RUBRICA_CRITERIO_ACTIVE ON TACTIVIDAD_RUBRICA_CRITERIO (PK_TACTIVIDAD_RUBRICA_CRITERIO) WHERE ACTIVE = true ;

--  Comentarios de columna (4)
COMMENT ON COLUMN TACTIVIDAD_RUBRICA_CRITERIO.PK_TACTIVIDAD_RUBRICA_CRITERIO IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TACTIVIDAD_RUBRICA_CRITERIO.FK_TACTIVIDAD IS 'Llave foranea a tabla TACTIVIDAD';
COMMENT ON COLUMN TACTIVIDAD_RUBRICA_CRITERIO.ORDEN IS 'Posicion del criterio en la rubrica';
COMMENT ON COLUMN TACTIVIDAD_RUBRICA_CRITERIO.NOMBRE IS 'Nombre del criterio (ej: Criterio 1)';

--  Comentario de tabla
COMMENT ON TABLE TACTIVIDAD_RUBRICA_CRITERIO IS 'Criterios de una rubrica de evaluacion (uno por registro, ordenados)';

-- --------------------------------------------------------------------------
--  Tabla: TACTIVIDAD_RUBRICA_NIVEL
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TACTIVIDAD_RUBRICA_NIVEL (
  PK_TACTIVIDAD_RUBRICA_NIVEL BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TACTIVIDAD_RUBRICA_CRITERIO BIGINT NOT NULL,
  DESCRIPCION VARCHAR(4000) NOT NULL,
  PONDERACION NUMERIC(5,2) NOT NULL,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TAC_RUBRICA_NIVEL PRIMARY KEY (PK_TACTIVIDAD_RUBRICA_NIVEL),
  CONSTRAINT UN_TAC_RUBRICA_NIVEL_1 UNIQUE (FK_TACTIVIDAD_RUBRICA_CRITERIO, PONDERACION) DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT FK_TAC_RUBRICA_NIVEL_1 FOREIGN KEY (FK_TACTIVIDAD_RUBRICA_CRITERIO) REFERENCES TACTIVIDAD_RUBRICA_CRITERIO (PK_TACTIVIDAD_RUBRICA_CRITERIO) ON DELETE CASCADE
);

--  Indices (2)
CREATE INDEX IF NOT EXISTS IDX_TAC_RUBRICA_NIVEL_1 ON TACTIVIDAD_RUBRICA_NIVEL (FK_TACTIVIDAD_RUBRICA_CRITERIO) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_RUBRICA_NIVEL_ACTIVE ON TACTIVIDAD_RUBRICA_NIVEL (PK_TACTIVIDAD_RUBRICA_NIVEL) WHERE ACTIVE = true ;

--  Comentarios de columna (3)
COMMENT ON COLUMN TACTIVIDAD_RUBRICA_NIVEL.PK_TACTIVIDAD_RUBRICA_NIVEL IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TACTIVIDAD_RUBRICA_NIVEL.FK_TACTIVIDAD_RUBRICA_CRITERIO IS 'Llave foranea a tabla TACTIVIDAD_RUBRICA_CRITERIO';
COMMENT ON COLUMN TACTIVIDAD_RUBRICA_NIVEL.PONDERACION IS 'Peso del nivel dentro de la rubrica, introducido libremente por el docente. Sin vinculo directo con TVALORACION institucional: la rubrica define su propia escala de pesos';
COMMENT ON COLUMN TACTIVIDAD_RUBRICA_NIVEL.DESCRIPCION IS 'Descripcion contextual del nivel de desempeno para el criterio de rubrica';

--  Comentario de tabla
COMMENT ON TABLE TACTIVIDAD_RUBRICA_NIVEL IS 'Niveles de desempeno definidos por el docente para cada criterio de rubrica. Cada nivel lleva su propio peso (PONDERACION) sin depender del catalogo institucional TVALORACION';

-- --------------------------------------------------------------------------
--  Tabla: TACTIVIDAD_RUBRICA_EVALUACION
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TACTIVIDAD_RUBRICA_EVALUACION (
  PK_TACTIVIDAD_RUBRICA_EVAL BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TACTIVIDAD_RUBRICA_CRITERIO BIGINT NOT NULL,
  FK_TACTIVIDAD_ESTUDIANTE BIGINT NOT NULL,
  PONDERACION NUMERIC(5,2) NOT NULL,
  OBSERVACION VARCHAR(4000),
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TAC_RUBRICA_EVAL PRIMARY KEY (PK_TACTIVIDAD_RUBRICA_EVAL),
  CONSTRAINT UN_TAC_RUBRICA_EVAL_1 UNIQUE (FK_TACTIVIDAD_RUBRICA_CRITERIO, FK_TACTIVIDAD_ESTUDIANTE) DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT FK_TAC_RUBRICA_EVAL_1 FOREIGN KEY (FK_TACTIVIDAD_RUBRICA_CRITERIO) REFERENCES TACTIVIDAD_RUBRICA_CRITERIO (PK_TACTIVIDAD_RUBRICA_CRITERIO) ON DELETE CASCADE,
  CONSTRAINT FK_TAC_RUBRICA_EVAL_2 FOREIGN KEY (FK_TACTIVIDAD_ESTUDIANTE) REFERENCES TACTIVIDAD_ESTUDIANTE (PK_TACTIVIDAD_ESTUDIANTE) ON DELETE CASCADE
);

--  Indices (3)
CREATE INDEX IF NOT EXISTS IDX_TAC_RUBRICA_EVAL_10 ON TACTIVIDAD_RUBRICA_EVALUACION (FK_TACTIVIDAD_RUBRICA_CRITERIO, FK_TACTIVIDAD_ESTUDIANTE) ;
CREATE INDEX IF NOT EXISTS IDX_TAC_RUBRICA_EVAL_1 ON TACTIVIDAD_RUBRICA_EVALUACION (FK_TACTIVIDAD_RUBRICA_CRITERIO) ;
CREATE INDEX IF NOT EXISTS IDX_TAC_RUBRICA_EVAL_2 ON TACTIVIDAD_RUBRICA_EVALUACION (FK_TACTIVIDAD_ESTUDIANTE) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_RUBRICA_EVALUACION_ACTIVE ON TACTIVIDAD_RUBRICA_EVALUACION (PK_TACTIVIDAD_RUBRICA_EVAL) WHERE ACTIVE = true ;

--  Comentarios de columna (4)
COMMENT ON COLUMN TACTIVIDAD_RUBRICA_EVALUACION.PK_TACTIVIDAD_RUBRICA_EVAL IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TACTIVIDAD_RUBRICA_EVALUACION.FK_TACTIVIDAD_RUBRICA_CRITERIO IS 'Llave foranea a tabla TACTIVIDAD_RUBRICA_CRITERIO';
COMMENT ON COLUMN TACTIVIDAD_RUBRICA_EVALUACION.FK_TACTIVIDAD_ESTUDIANTE IS 'Llave foranea a tabla TACTIVIDAD_ESTUDIANTE (estudiante evaluado)';
COMMENT ON COLUMN TACTIVIDAD_RUBRICA_EVALUACION.PONDERACION IS 'Peso del nivel seleccionado por el docente para este criterio/estudiante. Sin vinculo directo con TVALORACION institucional';

