COMMENT ON TABLE TACTIVIDAD_RUBRICA_EVALUACION IS 'Calificacion por criterio de rubrica: que peso (PONDERACION) se asigno a cada estudiante. Una fila por criterio x estudiante. Desacoplado del catalogo institucional TVALORACION';

-- --------------------------------------------------------------------------
--  Tabla: TACTIVIDAD_COTEJO_ITEM
