COMMENT ON COLUMN TACTIVIDAD_COTEJO_ITEM.FK_TACTIVIDAD IS 'Llave foranea a tabla TACTIVIDAD';
COMMENT ON COLUMN TACTIVIDAD_COTEJO_ITEM.DESCRIPCION IS 'Descripcion del item de la lista de cotejo';

