COMMENT ON COLUMN TACTIVIDAD_COTEJO_EVALUACION.FK_TACTIVIDAD_ESTUDIANTE IS 'Llave foranea a tabla TACTIVIDAD_ESTUDIANTE (estudiante evaluado)';
COMMENT ON COLUMN TACTIVIDAD_COTEJO_EVALUACION.CUMPLIDO IS 'Indica si el estudiante cumplio con el item (S/N). CHECK IN (S,N)';

