-- --------------------------------------------------------------------------
--  Tabla: TACTIVIDAD_ESCALA
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TACTIVIDAD_ESCALA (
  PK_TACTIVIDAD_ESCALA BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TACTIVIDAD BIGINT NOT NULL,
  CRITERIOS_GENERALES VARCHAR(4000),
  FK_TLV_TIPO_ESCALA BIGINT NOT NULL,
  VALOR_MIN NUMERIC(5,2),
  VALOR_MAX NUMERIC(5,2),
  INTERPRETACION_RANGOS VARCHAR(4000),
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TAC_ESCALA PRIMARY KEY (PK_TACTIVIDAD_ESCALA),
  CONSTRAINT UN_TAC_ESCALA_1 UNIQUE (FK_TACTIVIDAD) DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT FK_TAC_ESCALA_1 FOREIGN KEY (FK_TACTIVIDAD) REFERENCES TACTIVIDAD (PK_TACTIVIDAD) ON DELETE CASCADE,
  CONSTRAINT FK_TAC_ESCALA_2 FOREIGN KEY (FK_TLV_TIPO_ESCALA) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR)
);

--  Indices (3)
CREATE INDEX IF NOT EXISTS IDX_TAC_ESCALA_1 ON TACTIVIDAD_ESCALA (FK_TACTIVIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TAC_ESCALA_2 ON TACTIVIDAD_ESCALA (FK_TLV_TIPO_ESCALA) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_ESCALA_ACTIVE ON TACTIVIDAD_ESCALA (PK_TACTIVIDAD_ESCALA) WHERE ACTIVE = true ;

--  Comentarios de columna (6)
COMMENT ON COLUMN TACTIVIDAD_ESCALA.PK_TACTIVIDAD_ESCALA IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TACTIVIDAD_ESCALA.FK_TACTIVIDAD IS 'Llave foranea a tabla TACTIVIDAD (relacion 1:1)';
COMMENT ON COLUMN TACTIVIDAD_ESCALA.CRITERIOS_GENERALES IS 'Criterios generales de la escala, separados por coma';
COMMENT ON COLUMN TACTIVIDAD_ESCALA.FK_TLV_TIPO_ESCALA IS 'Tipo de escala. Llave foranea de lista valor para obtener TIPO_ESCALA. Valores: Numerica, Cualitativa';
COMMENT ON COLUMN TACTIVIDAD_ESCALA.VALOR_MIN IS 'Valor minimo del rango global de la escala (cuando TIPO_ESCALA = Numerica)';
COMMENT ON COLUMN TACTIVIDAD_ESCALA.VALOR_MAX IS 'Valor maximo del rango global de la escala (cuando TIPO_ESCALA = Numerica)';
COMMENT ON COLUMN TACTIVIDAD_ESCALA.INTERPRETACION_RANGOS IS 'Interpretacion textual de los rangos de la escala';

--  Comentario de tabla
COMMENT ON TABLE TACTIVIDAD_ESCALA IS 'Configuracion de la escala de valoracion de una actividad (1:1 con TACTIVIDAD cuando INSTRUMENTO = Escala). Contiene criterios generales, tipo (numerica/cualitativa), rango global e interpretacion';

