  CONSTRAINT FK_TAC_ESCALA_NIVEL_1 FOREIGN KEY (FK_TACTIVIDAD_ESCALA) REFERENCES TACTIVIDAD_ESCALA (PK_TACTIVIDAD_ESCALA) ON DELETE CASCADE
);

