--  Comentarios de columna (4)
COMMENT ON COLUMN TACTIVIDAD_ESCALA_NIVEL.PK_TACTIVIDAD_ESCALA_NIVEL IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TACTIVIDAD_ESCALA_NIVEL.FK_TACTIVIDAD_ESCALA IS 'Llave foranea a tabla TACTIVIDAD_ESCALA (niveles dentro de la escala)';
COMMENT ON COLUMN TACTIVIDAD_ESCALA_NIVEL.ORDEN IS 'Posicion del nivel dentro de la escala (1, 2, 3...)';
COMMENT ON COLUMN TACTIVIDAD_ESCALA_NIVEL.PONDERACION IS 'Peso del nivel dentro de la escala, introducido libremente por el docente. Sin vinculo directo con TVALORACION institucional';

--  Comentario de tabla
COMMENT ON TABLE TACTIVIDAD_ESCALA_NIVEL IS 'Niveles definidos por el docente para la escala de una actividad. Cada nivel lleva su propio peso (PONDERACION), desacoplado del catalogo institucional TVALORACION';

-- --------------------------------------------------------------------------
