  CONSTRAINT FK_TAC_ESCALA_EVAL_2 FOREIGN KEY (FK_TACTIVIDAD_ESTUDIANTE) REFERENCES TACTIVIDAD_ESTUDIANTE (PK_TACTIVIDAD_ESTUDIANTE) ON DELETE CASCADE
);

--  Indices (3)
