--  Comentarios de columna (5)
COMMENT ON COLUMN TACTIVIDAD_ESCALA_EVALUACION.PK_TACTIVIDAD_ESCALA_EVAL IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TACTIVIDAD_ESCALA_EVALUACION.FK_TACTIVIDAD_ESCALA IS 'Llave foranea a tabla TACTIVIDAD_ESCALA (escala evaluada)';
COMMENT ON COLUMN TACTIVIDAD_ESCALA_EVALUACION.FK_TACTIVIDAD_ESTUDIANTE IS 'Llave foranea a tabla TACTIVIDAD_ESTUDIANTE (estudiante evaluado)';
COMMENT ON COLUMN TACTIVIDAD_ESCALA_EVALUACION.VALOR IS 'Valor numerico asignado por el docente dentro del rango (VALOR_MIN..VALOR_MAX) de la escala';
COMMENT ON COLUMN TACTIVIDAD_ESCALA_EVALUACION.PONDERACION IS 'Peso del valor registrado (opcional, para escala cualitativa con niveles predefinidos). Sin vinculo directo con TVALORACION institucional';

--  Comentario de tabla
COMMENT ON TABLE TACTIVIDAD_ESCALA_EVALUACION IS 'Calificacion de un estudiante en una escala: valor numerico (numerica) o peso cualitativo via PONDERACION. Una fila por escala x estudiante. Desacoplado del catalogo institucional TVALORACION';

-- --------------------------------------------------------------------------
--  Tabla: TACTIVIDAD_ADAPTACION
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TACTIVIDAD_ADAPTACION (
  PK_TACTIVIDAD_ADAPTACION BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TACTIVIDAD BIGINT NOT NULL,
  FK_TLV_TIPO_ADAPTACION BIGINT NOT NULL,
