  USA_VERSION_MODIFICADA CHAR(1) DEFAULT 'N',
  FK_TARCHIVO BIGINT,
  FK_TLV_FORMATO_ADAPTACION BIGINT,
  FK_TLV_APLICA_A BIGINT,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TAC_ADAPTACION PRIMARY KEY (PK_TACTIVIDAD_ADAPTACION),
  CONSTRAINT CK_TAC_ADAPTACION_USA_VERSION CHECK (USA_VERSION_MODIFICADA IN ('S','N')),
  CONSTRAINT FK_TAC_ADAPTACION_1 FOREIGN KEY (FK_TACTIVIDAD) REFERENCES TACTIVIDAD (PK_TACTIVIDAD) ON DELETE CASCADE,
  CONSTRAINT FK_TAC_ADAPTACION_2 FOREIGN KEY (FK_TLV_TIPO_ADAPTACION) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TAC_ADAPTACION_3 FOREIGN KEY (FK_TLV_FORMATO_ADAPTACION) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TAC_ADAPTACION_4 FOREIGN KEY (FK_TLV_APLICA_A) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TAC_ADAPTACION_5 FOREIGN KEY (FK_TARCHIVO) REFERENCES TARCHIVO (PK_TARCHIVO)
);

--  Indices (6)
CREATE INDEX IF NOT EXISTS IDX_TAC_ADAPTACION_1 ON TACTIVIDAD_ADAPTACION (FK_TACTIVIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TAC_ADAPTACION_2 ON TACTIVIDAD_ADAPTACION (FK_TLV_TIPO_ADAPTACION) ;
CREATE INDEX IF NOT EXISTS IDX_TAC_ADAPTACION_3 ON TACTIVIDAD_ADAPTACION (FK_TLV_FORMATO_ADAPTACION) ;
CREATE INDEX IF NOT EXISTS IDX_TAC_ADAPTACION_4 ON TACTIVIDAD_ADAPTACION (FK_TLV_APLICA_A) ;
CREATE INDEX IF NOT EXISTS IDX_TAC_ADAPTACION_5 ON TACTIVIDAD_ADAPTACION (FK_TARCHIVO) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_ADAPTACION_ACTIVE ON TACTIVIDAD_ADAPTACION (PK_TACTIVIDAD_ADAPTACION) WHERE ACTIVE = true ;

--  Comentarios de columna (7)
COMMENT ON COLUMN TACTIVIDAD_ADAPTACION.PK_TACTIVIDAD_ADAPTACION IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TACTIVIDAD_ADAPTACION.FK_TACTIVIDAD IS 'Llave foranea a tabla TACTIVIDAD';
COMMENT ON COLUMN TACTIVIDAD_ADAPTACION.FK_TLV_TIPO_ADAPTACION IS 'Tipo de adaptacion curricular. Llave foranea de lista valor para obtener TIPO_ADAPTACION (ej: Discapacidad visual)';
COMMENT ON COLUMN TACTIVIDAD_ADAPTACION.DESCRIPCION IS 'Descripcion de como se adapta la actividad para este caso (max 500 caracteres)';
COMMENT ON COLUMN TACTIVIDAD_ADAPTACION.USA_VERSION_MODIFICADA IS 'Indica si se usa una version modificada del instrumento de evaluacion (S/N). CHECK IN (S,N)';
COMMENT ON COLUMN TACTIVIDAD_ADAPTACION.FK_TARCHIVO IS 'Archivo adjunto (plantilla modificada u otro recurso de la adaptacion). Llave foranea a tabla TARCHIVO';
COMMENT ON COLUMN TACTIVIDAD_ADAPTACION.FK_TLV_FORMATO_ADAPTACION IS 'Formato de la adaptacion (ej: pantalla, doc). Llave foranea de lista valor para obtener FORMATO_ADAPTACION';
COMMENT ON COLUMN TACTIVIDAD_ADAPTACION.FK_TLV_APLICA_A IS 'A quien se aplica la adaptacion (estudiante/grupo). Llave foranea de lista valor para obtener APLICA_A';

--  Comentario de tabla
COMMENT ON TABLE TACTIVIDAD_ADAPTACION IS 'Adaptaciones curriculares aplicadas a una actividad (opcional, una o varias por actividad)';

-- --------------------------------------------------------------------------
--  Tabla: TRUBRICA_UNIDAD
--  Rúbrica pedagógica asociada 1:1 a una unidad temática. Reemplaza el
--  modelo canónico de TLOGRO/TINDICADOR; sus criterios se ordenan dentro
--  de la rúbrica y conservan los niveles de valoración institucional.
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TRUBRICA_UNIDAD (
  PK_TRUBRICA_UNIDAD BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TUNIDAD BIGINT NOT NULL,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TRUBRICA_UNIDAD PRIMARY KEY (PK_TRUBRICA_UNIDAD),
  CONSTRAINT UN_TRUBRICA_UNIDAD_1 UNIQUE (FK_TUNIDAD),
  CONSTRAINT FK_TRUBRICA_UNIDAD_1 FOREIGN KEY (FK_TUNIDAD)
    REFERENCES TUNIDAD (PK_TUNIDAD) ON DELETE CASCADE
);

--  Indices (2)
CREATE INDEX IF NOT EXISTS IDX_TRUBRICA_UNIDAD_1 ON TRUBRICA_UNIDAD (FK_TUNIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TRUBRICA_UNIDAD_ACTIVE ON TRUBRICA_UNIDAD (PK_TRUBRICA_UNIDAD) WHERE ACTIVE = true ;

--  Comentarios de columna (2)
COMMENT ON COLUMN TRUBRICA_UNIDAD.PK_TRUBRICA_UNIDAD IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TRUBRICA_UNIDAD.FK_TUNIDAD IS 'Unidad temática propietaria de la rúbrica. Relación 1:1 con TUNIDAD';

--  Comentario de tabla
COMMENT ON TABLE TRUBRICA_UNIDAD IS 'Rúbrica pedagógica de la unidad (1:1 con TUNIDAD). Reemplaza TLOGRO/TINDICADOR como definición pedagógica de criterios y niveles';

-- --------------------------------------------------------------------------
--  Tabla: TCRITERIO_UNIDAD
--  Criterio de aprendizaje dentro de la rúbrica de la unidad. Conserva la
--  descripción del antiguo TLOGRO y la posición pedagógica dentro de la
--  rúbrica. No almacena asignatura, grupo, periodo ni docente: ese
--  esta en TUNIDAD.
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TCRITERIO_UNIDAD (
  PK_TCRITERIO_UNIDAD BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TRUBRICA_UNIDAD BIGINT NOT NULL,
  ORDEN NUMERIC(4) NOT NULL,
  DESCRIPCION VARCHAR(4000),
  PUBLICO VARCHAR(1) NOT NULL,
  CODIGO VARCHAR(6),
  DESCRIPTOR_PROM VARCHAR(1),
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TCRITERIO_UNIDAD PRIMARY KEY (PK_TCRITERIO_UNIDAD),
  CONSTRAINT UN_TCRITERIO_UNIDAD_1 UNIQUE (FK_TRUBRICA_UNIDAD, ORDEN),
  CONSTRAINT FK_TCRITERIO_UNIDAD_1 FOREIGN KEY (FK_TRUBRICA_UNIDAD)
    REFERENCES TRUBRICA_UNIDAD (PK_TRUBRICA_UNIDAD) ON DELETE CASCADE
);

--  Indices (3)
CREATE INDEX IF NOT EXISTS IDX_TCRITERIO_UNIDAD_1 ON TCRITERIO_UNIDAD (FK_TRUBRICA_UNIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TCRITERIO_UNIDAD_2 ON TCRITERIO_UNIDAD (FK_TRUBRICA_UNIDAD, ORDEN) ;
CREATE INDEX IF NOT EXISTS IDX_TCRITERIO_UNIDAD_ACTIVE ON TCRITERIO_UNIDAD (PK_TCRITERIO_UNIDAD) WHERE ACTIVE = true ;

--  Comentarios de columna (5)
COMMENT ON COLUMN TCRITERIO_UNIDAD.PK_TCRITERIO_UNIDAD IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TCRITERIO_UNIDAD.FK_TRUBRICA_UNIDAD IS 'Rúbrica propietaria del criterio. ON DELETE CASCADE';
COMMENT ON COLUMN TCRITERIO_UNIDAD.ORDEN IS 'Posición pedagógica del criterio dentro de la rúbrica (1, 2, 3, ...)';
COMMENT ON COLUMN TCRITERIO_UNIDAD.DESCRIPCION IS 'Texto del aprendizaje o competencia esperada';
COMMENT ON COLUMN TCRITERIO_UNIDAD.PUBLICO IS 'Visibilidad del criterio. CHECK IN (S, N)';
COMMENT ON COLUMN TCRITERIO_UNIDAD.CODIGO IS 'Codigo externo a presentar o identificar el registro al usuario';
COMMENT ON COLUMN TCRITERIO_UNIDAD.DESCRIPTOR_PROM IS 'Marcado de descriptor de promoción. CHECK IN (S, N)';

--  Comentario de tabla
COMMENT ON TABLE TCRITERIO_UNIDAD IS 'Criterio de aprendizaje dentro de la rúbrica de la unidad. Reemplaza TLOGRO (sin repetir asignatura, grupo, periodo ni docente)';

-- --------------------------------------------------------------------------
--  Tabla: TNIVEL_CRITERIO_UNIDAD
--  Descriptor del criterio para un nivel concreto de la escala
--  institucional. Conserva INDICADOR, RECOMENDACION y TAREA del antiguo
--  TINDICADOR. Apunta al puente TESCALA_VALORACION para que el descriptor
--  migre entre escalas sin perder consistencia.
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TNIVEL_CRITERIO_UNIDAD (
  PK_TNIVEL_CRITERIO_UNIDAD BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TCRITERIO_UNIDAD BIGINT NOT NULL,
  INDICADOR VARCHAR(4000),
  RECOMENDACION VARCHAR(400),
  TAREA VARCHAR(4000),
  FK_TESCALA_VALORACION BIGINT NOT NULL,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TNIVEL_CRITERIO_UNIDAD PRIMARY KEY (PK_TNIVEL_CRITERIO_UNIDAD),
  CONSTRAINT UN_TNIVEL_CRITERIO_UNIDAD_1 UNIQUE (FK_TCRITERIO_UNIDAD, FK_TESCALA_VALORACION),
  CONSTRAINT FK_TNIVEL_CRITERIO_UNIDAD_1 FOREIGN KEY (FK_TCRITERIO_UNIDAD)
    REFERENCES TCRITERIO_UNIDAD (PK_TCRITERIO_UNIDAD) ON DELETE CASCADE,
  CONSTRAINT FK_TNIVEL_CRITERIO_UNIDAD_2 FOREIGN KEY (FK_TESCALA_VALORACION)
    REFERENCES TESCALA_VALORACION (PK_TESCALA_VALORACION)
);

--  Indices (3)
CREATE INDEX IF NOT EXISTS IDX_TNIVEL_CRITERIO_UNIDAD_1 ON TNIVEL_CRITERIO_UNIDAD (FK_TCRITERIO_UNIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TNIVEL_CRITERIO_UNIDAD_2 ON TNIVEL_CRITERIO_UNIDAD (FK_TESCALA_VALORACION) ;
CREATE INDEX IF NOT EXISTS IDX_TNIVEL_CRITERIO_UNIDAD_ACTIVE ON TNIVEL_CRITERIO_UNIDAD (PK_TNIVEL_CRITERIO_UNIDAD) WHERE ACTIVE = true ;

--  Comentarios de columna (5)
COMMENT ON COLUMN TNIVEL_CRITERIO_UNIDAD.PK_TNIVEL_CRITERIO_UNIDAD IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TNIVEL_CRITERIO_UNIDAD.FK_TCRITERIO_UNIDAD IS 'Criterio propietario del nivel. ON DELETE CASCADE';
COMMENT ON COLUMN TNIVEL_CRITERIO_UNIDAD.INDICADOR IS 'Descriptor textual del nivel de desempeño';
COMMENT ON COLUMN TNIVEL_CRITERIO_UNIDAD.RECOMENDACION IS 'Recomendación pedagógica opcional para el nivel';
COMMENT ON COLUMN TNIVEL_CRITERIO_UNIDAD.TAREA IS 'Tarea o actividad adicional sugerida para el nivel (opcional)';
COMMENT ON COLUMN TNIVEL_CRITERIO_UNIDAD.FK_TESCALA_VALORACION IS 'Par escala-valoración institucional al que se asocia el nivel';

--  Comentario de tabla
COMMENT ON TABLE TNIVEL_CRITERIO_UNIDAD IS 'Nivel de desempeño dentro de un criterio de la rúbrica de la unidad. Reemplaza TINDICADOR y conserva INDICADOR, RECOMENDACION y TAREA';

-- --------------------------------------------------------------------------
--  Tabla: TUNIDAD_NOTA
--  Nota agregada de la unidad por matrícula. Se calcula como promedio
--  ponderado de las notas de las actividades de la unidad, usando
--  TACTIVIDAD.INFLUENCIA como peso. CALIFICACION, RECUPERACION y
--  DEFINITIVA aplican la misma fórmula sobre sus respectivas columnas
--  no nulas en TACTIVIDAD_NOTA.
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TUNIDAD_NOTA (
  PK_TUNIDAD_NOTA BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TUNIDAD BIGINT NOT NULL,
  FK_TMATRICULA BIGINT NOT NULL,
  CALIFICACION NUMERIC(5,2),
  RECUPERACION NUMERIC(5,2),
  DEFINITIVA NUMERIC(5,2),
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TUNIDAD_NOTA PRIMARY KEY (PK_TUNIDAD_NOTA),
  CONSTRAINT UN_TUNIDAD_NOTA_1 UNIQUE (FK_TUNIDAD, FK_TMATRICULA),
  CONSTRAINT FK_TUNIDAD_NOTA_1 FOREIGN KEY (FK_TUNIDAD)
    REFERENCES TUNIDAD (PK_TUNIDAD),
  CONSTRAINT FK_TUNIDAD_NOTA_2 FOREIGN KEY (FK_TMATRICULA)
    REFERENCES TMATRICULA (PK_TMATRICULA)
);

--  Indices (3)
CREATE INDEX IF NOT EXISTS IDX_TUNIDAD_NOTA_1 ON TUNIDAD_NOTA (FK_TUNIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TUNIDAD_NOTA_2 ON TUNIDAD_NOTA (FK_TMATRICULA) ;
CREATE INDEX IF NOT EXISTS IDX_TUNIDAD_NOTA_ACTIVE ON TUNIDAD_NOTA (PK_TUNIDAD_NOTA) WHERE ACTIVE = true ;

--  Comentarios de columna (4)
COMMENT ON COLUMN TUNIDAD_NOTA.PK_TUNIDAD_NOTA IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TUNIDAD_NOTA.FK_TUNIDAD IS 'Unidad evaluada. Parte de UNIQUE (FK_TUNIDAD, FK_TMATRICULA)';
COMMENT ON COLUMN TUNIDAD_NOTA.FK_TMATRICULA IS 'Matrícula evaluada. Parte de UNIQUE (FK_TUNIDAD, FK_TMATRICULA)';
COMMENT ON COLUMN TUNIDAD_NOTA.CALIFICACION IS 'Promedio ponderado de CALIFICACION en TACTIVIDAD_NOTA por INFLUENCIA';
COMMENT ON COLUMN TUNIDAD_NOTA.RECUPERACION IS 'Promedio ponderado de RECUPERACION en TACTIVIDAD_NOTA por INFLUENCIA';
COMMENT ON COLUMN TUNIDAD_NOTA.DEFINITIVA IS 'Promedio ponderado de DEFINITIVA en TACTIVIDAD_NOTA por INFLUENCIA';

--  Comentario de tabla
COMMENT ON TABLE TUNIDAD_NOTA IS 'Nota agregada de una unidad por matrícula (promedio ponderado de TACTIVIDAD_NOTA por TACTIVIDAD.INFLUENCIA)';

-- --------------------------------------------------------------------------
--  Tabla: TACTIVIDAD_RECUPERACION
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TACTIVIDAD_RECUPERACION (
  PK_TACTIVIDAD_RECUPERACION BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TACTIVIDAD BIGINT NOT NULL,
  FK_TLV_DESTINO_RECUPERACION BIGINT NOT NULL,
  FK_TACTIVIDAD_RECUPERAR BIGINT,
  FK_TLV_TIPO_APLICACION_RECUPERACION BIGINT NOT NULL,
  FK_TLV_TIPO_CALCULO_RECUPERACION BIGINT NOT NULL,
  VALOR_PONDERACION_RECUPERACION NUMERIC(5,2),
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TAC_RECUPERACION PRIMARY KEY (PK_TACTIVIDAD_RECUPERACION),
  CONSTRAINT UN_TAC_RECUPERACION_1 UNIQUE (FK_TACTIVIDAD) DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT FK_TAC_RECUPERACION_1 FOREIGN KEY (FK_TACTIVIDAD) REFERENCES TACTIVIDAD (PK_TACTIVIDAD) ON DELETE CASCADE,
  CONSTRAINT FK_TAC_RECUPERACION_2 FOREIGN KEY (FK_TLV_DESTINO_RECUPERACION) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TAC_RECUPERACION_3 FOREIGN KEY (FK_TACTIVIDAD_RECUPERAR) REFERENCES TACTIVIDAD (PK_TACTIVIDAD) ON DELETE SET NULL,
  CONSTRAINT FK_TAC_RECUPERACION_4 FOREIGN KEY (FK_TLV_TIPO_APLICACION_RECUPERACION) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TAC_RECUPERACION_5 FOREIGN KEY (FK_TLV_TIPO_CALCULO_RECUPERACION) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR)
);

--  Indices (6)
CREATE INDEX IF NOT EXISTS IDX_TAC_RECUPERACION_1 ON TACTIVIDAD_RECUPERACION (FK_TACTIVIDAD) ;
CREATE INDEX IF NOT EXISTS IDX_TAC_RECUPERACION_2 ON TACTIVIDAD_RECUPERACION (FK_TLV_DESTINO_RECUPERACION) ;
CREATE INDEX IF NOT EXISTS IDX_TAC_RECUPERACION_3 ON TACTIVIDAD_RECUPERACION (FK_TACTIVIDAD_RECUPERAR) ;
CREATE INDEX IF NOT EXISTS IDX_TAC_RECUPERACION_4 ON TACTIVIDAD_RECUPERACION (FK_TLV_TIPO_APLICACION_RECUPERACION) ;
CREATE INDEX IF NOT EXISTS IDX_TAC_RECUPERACION_5 ON TACTIVIDAD_RECUPERACION (FK_TLV_TIPO_CALCULO_RECUPERACION) ;
CREATE INDEX IF NOT EXISTS IDX_TACTIVIDAD_RECUPERACION_ACTIVE ON TACTIVIDAD_RECUPERACION (PK_TACTIVIDAD_RECUPERACION) WHERE ACTIVE = true ;

--  Comentarios de columna (7)
COMMENT ON COLUMN TACTIVIDAD_RECUPERACION.PK_TACTIVIDAD_RECUPERACION IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TACTIVIDAD_RECUPERACION.FK_TACTIVIDAD IS 'Actividad de recuperacion (la que ES_RECUPERACION = S en TACTIVIDAD). Relacion 1:1';
COMMENT ON COLUMN TACTIVIDAD_RECUPERACION.FK_TLV_DESTINO_RECUPERACION IS 'Destino de la recuperacion. Llave foranea de lista valor para obtener DESTINO_RECUPERACION. Valores: ACTIVIDAD, NOTA_FINAL';
COMMENT ON COLUMN TACTIVIDAD_RECUPERACION.FK_TACTIVIDAD_RECUPERAR IS 'Actividad original que se recupera (NULL cuando FK_TLV_DESTINO_RECUPERACION = NOTA_FINAL). Self-FK a TACTIVIDAD distinto del FK_TACTIVIDAD jerarquico';
COMMENT ON COLUMN TACTIVIDAD_RECUPERACION.FK_TLV_TIPO_APLICACION_RECUPERACION IS 'Como se aplica la nota de recuperacion. Llave foranea de lista valor para obtener TIPO_APLICACION_RECUPERACION. Valores: COMPUTAR (computar con la nota anterior), REEMPLAZAR (reemplazar la nota actual)';
COMMENT ON COLUMN TACTIVIDAD_RECUPERACION.FK_TLV_TIPO_CALCULO_RECUPERACION IS 'Como se calcula la nota final. Llave foranea de lista valor para obtener TIPO_CALCULO_RECUPERACION. Valores: PROMEDIADO, PONDERADO';
COMMENT ON COLUMN TACTIVIDAD_RECUPERACION.VALOR_PONDERACION_RECUPERACION IS 'Peso de la nota de recuperacion cuando TIPO_CALCULO_RECUPERACION = PONDERADO (0-100, complemento de la actividad original)';

--  Comentario de tabla
COMMENT ON TABLE TACTIVIDAD_RECUPERACION IS 'Configuracion de una actividad de recuperacion (1:1 con TACTIVIDAD). Define a quien se le aplica (ACTIVIDAD o NOTA_FINAL), cual actividad recupera, como se aplica (computar/reemplazar) y como se calcula (promediado/ponderado)';

-- --------------------------------------------------------------------------
