  CALIFICAR_CRITERIOS bool_sn,
  FK_TLV_CALCULO_DESCRIPTOR BIGINT,
  CALIFICAR_ACTIVIDADES bool_sn,
  INFLUYE_DESEMPLENO_ACADEMICO bool_sn DEFAULT 'S',
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
