  CONSTRAINT FK_TASIGNATURA_PLAN_9 FOREIGN KEY (FK_TLV_CALCULO_DESCRIPTOR) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TASIGNATURA_PLAN_6 FOREIGN KEY (FK_TLV_MODELO_CALIFICACION_DEF) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TASIGNATURA_PLAN_8 FOREIGN KEY (FK_TLV_CALCULO_DEFINITIVA) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TASIGNATURA_PLAN_5 FOREIGN KEY (FK_TLV_FORMATO_CALIFICACION_DEF) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TASIGNATURA_PLAN_4 FOREIGN KEY (FK_TLV_FORMATO_CALIFICACION_ACT) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR),
  CONSTRAINT FK_TASIGNATURA_PLAN_1 FOREIGN KEY (FK_TPLAN) REFERENCES TPLAN (PK_TPLAN),
  CONSTRAINT FK_TASIGNATURA_PLAN_7 FOREIGN KEY (FK_TLV_ELEMENTO_CALCULO_DEF) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR)
);

