COMMENT ON COLUMN TASIGNATURA_PLAN.FK_TASIGNATURA IS 'Llave foranea a tabla TASIGNATURA';
COMMENT ON COLUMN TASIGNATURA_PLAN.FK_TLV_FORMATO_CALIFICACION_ACT IS 'Llave foranea a tabla TLISTA_VALOR para obtener FORMATO_CALIFICACION_ACT';
COMMENT ON COLUMN TASIGNATURA_PLAN.FK_TLV_FORMATO_CALIFICACION_DEF IS 'Llave foranea a tabla TLISTA_VALOR para obtener FORMATO_CALIFICACION_DEF';
COMMENT ON COLUMN TASIGNATURA_PLAN.FK_TLV_MODELO_CALIFICACION_DEF IS 'Llave foranea a tabla TLISTA_VALOR para obtener MODELO_CALIFICACION_DEF';
COMMENT ON COLUMN TASIGNATURA_PLAN.FK_TLV_ELEMENTO_CALCULO_DEF IS 'Llave foranea de lista valor para obtener ELEMENTO_CALCULO_DEF';
