-- --------------------------------------------------------------------------
--  Tabla: TCRITERIO_EVALUACION_ASIGNATURA_PLAN
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TCRITERIO_EVALUACION_ASIGNATURA_PLAN (
  PK_TCRITERIO_EVALUACION_ASIGNATURA_PLAN BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TCRITERIO_EVALUACION BIGINT NOT NULL,
  FK_TASIGNATURA_PLAN BIGINT NOT NULL,
  FK_TGRADO BIGINT,
  POR_DEFECTO bool_sn NOT NULL DEFAULT 'N',
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT UN_TCE_ASIG_PLAN_1 UNIQUE (FK_TCRITERIO_EVALUACION, FK_TASIGNATURA_PLAN) DEFERRABLE INITIALLY DEFERRED,
  CONSTRAINT PK_TCE_ASIG_PLAN PRIMARY KEY (PK_TCRITERIO_EVALUACION_ASIGNATURA_PLAN),
  CONSTRAINT FK_TCE_ASIG_PLAN_1 FOREIGN KEY (FK_TCRITERIO_EVALUACION) REFERENCES TCRITERIO_EVALUACION (PK_TCRITERIO_EVALUACION),
  CONSTRAINT FK_TCE_ASIG_PLAN_2 FOREIGN KEY (FK_TASIGNATURA_PLAN) REFERENCES TASIGNATURA_PLAN (PK_TASIGNATURA_PLAN),
  CONSTRAINT FK_TCE_ASIG_PLAN_3 FOREIGN KEY (FK_TGRADO) REFERENCES TGRADO (PK_TGRADO),
  CONSTRAINT CHK_TCE_ASIG_PLAN_INHERIT CHECK (
    (POR_DEFECTO = 'S' AND FK_TGRADO IS NULL)
    OR (POR_DEFECTO = 'N' AND FK_TGRADO IS NOT NULL)
  )
);

--  Indices (5)
CREATE INDEX IF NOT EXISTS IDX_TCE_ASIG_PLAN_1 ON TCRITERIO_EVALUACION_ASIGNATURA_PLAN (FK_TASIGNATURA_PLAN) ;
