CREATE INDEX IF NOT EXISTS IDX_TCE_ASIG_PLAN_4 ON TCRITERIO_EVALUACION_ASIGNATURA_PLAN (POR_DEFECTO) ;

--  Unicidad por herencia (partial unique indexes; Postgres trata NULL como distinto)
CREATE UNIQUE INDEX IF NOT EXISTS UN_TCE_ASIG_PLAN_DEFAULT
  ON TCRITERIO_EVALUACION_ASIGNATURA_PLAN (FK_TCRITERIO_EVALUACION, FK_TASIGNATURA_PLAN)
  WHERE FK_TGRADO IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS UN_TCE_ASIG_PLAN_OVERRIDE
  ON TCRITERIO_EVALUACION_ASIGNATURA_PLAN (FK_TCRITERIO_EVALUACION, FK_TASIGNATURA_PLAN, FK_TGRADO)
  WHERE FK_TGRADO IS NOT NULL;
CREATE INDEX IF NOT EXISTS IDX_TCRITERIO_EVALUACION_ASIGNATURA_PLAN_ACTIVE ON TCRITERIO_EVALUACION_ASIGNATURA_PLAN (PK_TCRITERIO_EVALUACION_ASIGNATURA_PLAN) WHERE ACTIVE = true ;

--  Comentarios de columna (5)
COMMENT ON COLUMN TCRITERIO_EVALUACION_ASIGNATURA_PLAN.PK_TCRITERIO_EVALUACION_ASIGNATURA_PLAN IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TCRITERIO_EVALUACION_ASIGNATURA_PLAN.FK_TCRITERIO_EVALUACION IS 'Llave foranea a tabla TCRITERIO_EVALUACION';
COMMENT ON COLUMN TCRITERIO_EVALUACION_ASIGNATURA_PLAN.FK_TASIGNATURA_PLAN IS 'Llave foranea a tabla TASIGNATURA_PLAN';
COMMENT ON COLUMN TCRITERIO_EVALUACION_ASIGNATURA_PLAN.FK_TGRADO IS 'NULL = instituye el default institucional; NOT NULL = override por grado especifico';
COMMENT ON COLUMN TCRITERIO_EVALUACION_ASIGNATURA_PLAN.POR_DEFECTO IS 'S = esta fila es el default institucional; N = override por grado';

