  CONSTRAINT FK_TCRITERIO_PROMOCION_ASIGNATURA_OBLIGATORIA_1 FOREIGN KEY (FK_TCRITERIO_PROMOCION) REFERENCES TCRITERIO_PROMOCION (PK_TCRITERIO_PROMOCION),
  CONSTRAINT FK_TCRITERIO_PROMOCION_ASIGNATURA_OBLIGATORIA_2 FOREIGN KEY (FK_TASIGNATURA) REFERENCES TASIGNATURA (PK_TASIGNATURA)
