-- ===========================================================================
--  FASE 2: FOREIGN KEYS de ciclos irreducibles (orden topologico no permite inlinearlos)
--  Conjunto minimo de arcos de retroalimentacion (3). El resto quedo inline.
-- ===========================================================================

-- Tabla TSEDE
-- pg_constraint.conname se almacena en lowercase cuando el nombre no está quotado,
-- por eso la comparacion usa LOWER() para evitar falso negativo en re-ejecucion.
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = LOWER('FK_TSEDE_1')) THEN
    ALTER TABLE TSEDE ADD CONSTRAINT FK_TSEDE_1 FOREIGN KEY (FK_TESTABLECIMIENTO) REFERENCES TESTABLECIMIENTO (PK_ESTABLECIMIENTO) ;
  END IF;
END $$;

