COMMENT ON COLUMN TACTIVIDAD_EXTRACURRICULAR.LOGROS_RECONOCIMIENTOS IS 'Logros o reconocimientos obtenidos en la actividad';
COMMENT ON COLUMN TACTIVIDAD_EXTRACURRICULAR.COMENTARIOS_ADICIONALES IS 'Comentarios adicionales sobre la participacion del estudiante';

-- --------------------------------------------------------------------------
--  Tabla: TLOGRO_RECONOCIMIENTO
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TLOGRO_RECONOCIMIENTO (
  PK_TLOGRO_RECONOCIMIENTO BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TOBSERVADOR BIGINT NOT NULL,
  FECHA DATE NOT NULL,
  FK_TLV_TIPO_LOGRO BIGINT NOT NULL,
  DESCRIPCION VARCHAR(4000) NOT NULL,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TLOGRO_RECONOCIMIENTO PRIMARY KEY (PK_TLOGRO_RECONOCIMIENTO),
  CONSTRAINT FK_TLOGRO_RECONOCIMIENTO_1 FOREIGN KEY (FK_TOBSERVADOR) REFERENCES TOBSERVADOR (PK_TOBSERVADOR) ON DELETE CASCADE,
  CONSTRAINT FK_TLOGRO_RECONOCIMIENTO_2 FOREIGN KEY (FK_TLV_TIPO_LOGRO) REFERENCES TLISTA_VALOR (PK_LISTA_VALOR)
);

--  Indices (4)
CREATE INDEX IF NOT EXISTS IDX_TLOGRO_RECONOCIMIENTO_1 ON TLOGRO_RECONOCIMIENTO (FK_TOBSERVADOR) ;
CREATE INDEX IF NOT EXISTS IDX_TLOGRO_RECONOCIMIENTO_2 ON TLOGRO_RECONOCIMIENTO (FK_TLV_TIPO_LOGRO) ;
CREATE INDEX IF NOT EXISTS IDX_TLOGRO_RECONOCIMIENTO_3 ON TLOGRO_RECONOCIMIENTO (FECHA) ;
CREATE INDEX IF NOT EXISTS IDX_TLOGRO_RECONOCIMIENTO_ACTIVE ON TLOGRO_RECONOCIMIENTO (PK_TLOGRO_RECONOCIMIENTO) WHERE ACTIVE = true ;

--  Comentarios de columna (6)
COMMENT ON COLUMN TLOGRO_RECONOCIMIENTO.PK_TLOGRO_RECONOCIMIENTO IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TLOGRO_RECONOCIMIENTO.FK_TOBSERVADOR IS 'Llave foranea a tabla TOBSERVADOR. Registro del perfil permanente del estudiante.';
COMMENT ON COLUMN TLOGRO_RECONOCIMIENTO.FECHA IS 'Fecha en que se obtuvo el logro o reconocimiento';
COMMENT ON COLUMN TLOGRO_RECONOCIMIENTO.FK_TLV_TIPO_LOGRO IS 'Tipo de logro o reconocimiento. Llave foranea de lista valor para obtener TIPO_LOGRO. Valores: Participaciones destacadas, Premios academicos, Certificaciones';
COMMENT ON COLUMN TLOGRO_RECONOCIMIENTO.DESCRIPCION IS 'Descripcion del logro o reconocimiento obtenido';

