CREATE INDEX IF NOT EXISTS IDX_TOBSERVADOR_RECOMENDACION_ACTIVE ON TOBSERVADOR_RECOMENDACION (PK_TOBSERVADOR_RECOMENDACION) WHERE ACTIVE = true ;

--  Comentarios de columna (6)
COMMENT ON COLUMN TOBSERVADOR_RECOMENDACION.PK_TOBSERVADOR_RECOMENDACION IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TOBSERVADOR_RECOMENDACION.FK_TOBSERVADOR IS 'Llave foranea a tabla TOBSERVADOR. Registro del perfil permanente del estudiante.';
COMMENT ON COLUMN TOBSERVADOR_RECOMENDACION.FECHA IS 'Fecha de la observacion o sugerencia';
COMMENT ON COLUMN TOBSERVADOR_RECOMENDACION.FK_TLV_TIPO_RECOMENDACION IS 'Tipo de observacion o sugerencia. Llave foranea de lista valor para obtener TIPO_RECOMENDACION. Valores: Recomendaciones, Comportamiento, Rendimiento academico';
COMMENT ON COLUMN TOBSERVADOR_RECOMENDACION.DESCRIPCION IS 'Descripcion de la observacion o sugerencia';

-- --------------------------------------------------------------------------
--  Tabla: TOBSERVADOR_ANOTACION_EVIDENCIA
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS TOBSERVADOR_ANOTACION_EVIDENCIA (
  PK_TOBSERVADOR_ANOTACION_EVIDENCIA BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  FK_TOBSERVADOR_ANOTACION BIGINT NOT NULL,
  FK_TARCHIVO BIGINT NOT NULL,
  FECHA DATE,
  CREATED_BY VARCHAR(120) NOT NULL,
  CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
  MODIFIED_BY VARCHAR(120),
  MODIFIED_AT TIMESTAMP,
  ACTIVE BOOLEAN DEFAULT TRUE NOT NULL,
  CONSTRAINT PK_TOBSERVADOR_ANOTACION_EVIDENCIA PRIMARY KEY (PK_TOBSERVADOR_ANOTACION_EVIDENCIA),
  CONSTRAINT FK_TOBS_ANOT_EVID_1 FOREIGN KEY (FK_TOBSERVADOR_ANOTACION) REFERENCES TOBSERVADOR_ANOTACION (PK_TOBSERVADOR_ANOTACION) ON DELETE CASCADE,
  CONSTRAINT FK_TOBS_ANOT_EVID_2 FOREIGN KEY (FK_TARCHIVO) REFERENCES TARCHIVO (PK_TARCHIVO)
);

--  Indices (3)
CREATE INDEX IF NOT EXISTS IDX_TOBS_ANOT_EVID_1 ON TOBSERVADOR_ANOTACION_EVIDENCIA (FK_TOBSERVADOR_ANOTACION) ;
CREATE INDEX IF NOT EXISTS IDX_TOBS_ANOT_EVID_2 ON TOBSERVADOR_ANOTACION_EVIDENCIA (FK_TARCHIVO) ;
CREATE INDEX IF NOT EXISTS IDX_TOBSERVADOR_ANOTACION_EVIDENCIA_ACTIVE ON TOBSERVADOR_ANOTACION_EVIDENCIA (PK_TOBSERVADOR_ANOTACION_EVIDENCIA) WHERE ACTIVE = true ;

--  Comentarios de columna (4)
COMMENT ON COLUMN TOBSERVADOR_ANOTACION_EVIDENCIA.PK_TOBSERVADOR_ANOTACION_EVIDENCIA IS 'Llave primaria de la tabla';
COMMENT ON COLUMN TOBSERVADOR_ANOTACION_EVIDENCIA.FK_TOBSERVADOR_ANOTACION IS 'Llave foranea a tabla TOBSERVADOR_ANOTACION';
COMMENT ON COLUMN TOBSERVADOR_ANOTACION_EVIDENCIA.FK_TARCHIVO IS 'Llave foranea a tabla TARCHIVO';
COMMENT ON COLUMN TOBSERVADOR_ANOTACION_EVIDENCIA.FECHA IS 'Fecha en que se registro la evidencia';

-- ==========================================================================
--  Vistas materializadas (PostgreSQL, NO Oracle)
--  Sintaxis CREATE MATERIALIZED VIEW ... WITH DATA (PostgreSQL nativo).
--  Refrescar con: REFRESH MATERIALIZED VIEW CONCURRENTLY <nombre>;
--  Requiere UNIQUE INDEX previo para CONCURRENTLY.
-- ==========================================================================

-- --------------------------------------------------------------------------
--  Vista materializada: VM_PROMOCION_ANUAL
-- --------------------------------------------------------------------------
--  Determina que estudiantes fueron promovidos al final del periodo
--  academico, con base en:
--    - Notas agregadas del ano (TASIGNATURA_DEFINITIVA)
--    - Criterios de promocion aplicados en la matricula
--      (TMATRICULA_SOCIOECONOMICO.FK_TLV_CONDICION_PROMOCION)
--    - Situacion academica final (TMATRICULA.FK_TLV_SITUACION_ACADEMICA)
--    - Evidencia de promocion: existe TMATRICULA siguiente con
--      FK_TMATRICULA_ANTERIOR apuntando a esta.
--
--  Nota: TMATRICULA_PROMOCION es para promociones excepcionales
--  (anticipada/retroactiva a mitad de periodo) y NO se incluye aqui.
-- --------------------------------------------------------------------------

DO $$ BEGIN
  -- pg_matviews.matviewname se almacena en lowercase cuando el nombre no está quotado,
  -- por eso la comparacion usa LOWER() para evitar falso negativo en re-ejecucion.
  IF NOT EXISTS (SELECT 1 FROM pg_matviews WHERE matviewname = LOWER('VM_PROMOCION_ANUAL')) THEN
    CREATE MATERIALIZED VIEW VM_PROMOCION_ANUAL AS
    SELECT
      m.PK_TMATRICULA,
      m.FK_TESTUDIANTE,
      m.FK_TGRUPO,
      gr.FK_TPERIODO_ACADEMICO,
      m.FK_TLV_ESTADO_MATRICULA,
      m.FK_TLV_SITUACION_ACADEMICA,
      ms.FK_TLV_CONDICION_PROMOCION,
      m.LISTA_MENSAJE_PROMOCION,
      -- Agregados cuantitativos del ano lectivo (TASIGNATURA_DEFINITIVA)
      COUNT(td.PK_TASIGNATURA_DEFINITIVA) AS TOTAL_ASIGNATURAS,
      ROUND(AVG(td.DEFINITIVA)::numeric, 2) AS PROMEDIO_GENERAL,
      SUM(CASE WHEN td.DEFINITIVA >= 3.0 THEN 1 ELSE 0 END) AS ASIGNATURAS_APROBADAS,
      SUM(CASE WHEN td.DEFINITIVA < 3.0 THEN 1 ELSE 0 END) AS ASIGNATURAS_REPROBADAS,
      MIN(td.DEFINITIVA) AS NOTA_MINIMA,
      MAX(td.DEFINITIVA) AS NOTA_MAXIMA,
      -- Estado calculado de promocion: PROMOVIDO si existe matricula siguiente
      CASE
        WHEN EXISTS (
          SELECT 1 FROM TMATRICULA next_m
          WHERE next_m.FK_TMATRICULA_ANTERIOR = m.PK_TMATRICULA
        ) THEN 'PROMOVIDO'::text
        ELSE 'NO_PROMOVIDO'::text
      END AS ESTADO_PROMOCION
    FROM TMATRICULA m
    LEFT JOIN TGRUPO g ON g.PK_TGRUPO = m.FK_TGRUPO
    LEFT JOIN TGRADO gr ON gr.PK_TGRADO = g.FK_TGRADO
    LEFT JOIN TMATRICULA_SOCIOECONOMICO ms ON ms.FK_TMATRICULA = m.PK_TMATRICULA
    LEFT JOIN TASIGNATURA_DEFINITIVA td ON td.FK_TMATRICULA = m.PK_TMATRICULA
    GROUP BY
      m.PK_TMATRICULA, m.FK_TESTUDIANTE, m.FK_TGRUPO, gr.FK_TPERIODO_ACADEMICO,
      m.FK_TLV_ESTADO_MATRICULA, m.FK_TLV_SITUACION_ACADEMICA,
      ms.FK_TLV_CONDICION_PROMOCION, m.LISTA_MENSAJE_PROMOCION
    WITH DATA;
  END IF;
END $$;

-- Indice unico (requerido para REFRESH CONCURRENTLY)
CREATE UNIQUE INDEX IF NOT EXISTS VM_PROMOCION_ANUAL_PK ON VM_PROMOCION_ANUAL (PK_TMATRICULA);

-- Indices secundarios para queries frecuentes
CREATE INDEX IF NOT EXISTS VM_PROMOCION_ANUAL_ESTUDIANTE ON VM_PROMOCION_ANUAL (FK_TESTUDIANTE);
CREATE INDEX IF NOT EXISTS VM_PROMOCION_ANUAL_PERIODO ON VM_PROMOCION_ANUAL (FK_TPERIODO_ACADEMICO);
CREATE INDEX IF NOT EXISTS VM_PROMOCION_ANUAL_GRUPO ON VM_PROMOCION_ANUAL (FK_TGRUPO);
CREATE INDEX IF NOT EXISTS VM_PROMOCION_ANUAL_CONDICION ON VM_PROMOCION_ANUAL (FK_TLV_CONDICION_PROMOCION);
CREATE INDEX IF NOT EXISTS VM_PROMOCION_ANUAL_ESTADO ON VM_PROMOCION_ANUAL (ESTADO_PROMOCION);

-- Comentarios
COMMENT ON MATERIALIZED VIEW VM_PROMOCION_ANUAL IS 'Determina que estudiantes fueron promovidos al final del periodo academico, cruzando TMATRICULA (criterios y situacion) con TASIGNATURA_DEFINITIVA (notas agregadas). Una fila por matricula × periodo. Detecta promocion via EXISTS en TMATRICULA siguiente. Refrescar con REFRESH MATERIALIZED VIEW CONCURRENTLY VM_PROMOCION_ANUAL';

COMMENT ON COLUMN VM_PROMOCION_ANUAL.PK_TMATRICULA IS 'PK de TMATRICULA';
COMMENT ON COLUMN VM_PROMOCION_ANUAL.FK_TESTUDIANTE IS 'Estudiante evaluado';
COMMENT ON COLUMN VM_PROMOCION_ANUAL.FK_TGRUPO IS 'Grupo al que pertenece la matricula en el periodo';
COMMENT ON COLUMN VM_PROMOCION_ANUAL.FK_TPERIODO_ACADEMICO IS 'Periodo academico (ano lectivo)';
COMMENT ON COLUMN VM_PROMOCION_ANUAL.FK_TLV_ESTADO_MATRICULA IS 'Estado de la matricula (ACTIVA / RETIRADO / etc)';
COMMENT ON COLUMN VM_PROMOCION_ANUAL.FK_TLV_SITUACION_ACADEMICA IS 'Situacion academica final del estudiante (APROBADO / REPROBADO / etc)';
COMMENT ON COLUMN VM_PROMOCION_ANUAL.FK_TLV_CONDICION_PROMOCION IS 'Condicion aplicada para la promocion (PROMOCION_AUTOMATICA / PROMOCION_CONDICIONADA / NO_PROMOCION / etc)';
COMMENT ON COLUMN VM_PROMOCION_ANUAL.LISTA_MENSAJE_PROMOCION IS 'Mensaje institucional de promocion (FK a TLISTA_VALOR)';
COMMENT ON COLUMN VM_PROMOCION_ANUAL.TOTAL_ASIGNATURAS IS 'Total de asignaturas evaluadas (COUNT desde TASIGNATURA_DEFINITIVA)';
COMMENT ON COLUMN VM_PROMOCION_ANUAL.PROMEDIO_GENERAL IS 'Promedio general del ano (AVG de TASIGNATURA_DEFINITIVA.DEFINITIVA, redondeado a 2 decimales)';
COMMENT ON COLUMN VM_PROMOCION_ANUAL.ASIGNATURAS_APROBADAS IS 'Cantidad de asignaturas con DEFINITIVA >= 3.0 (umbral institucional ajustable)';
COMMENT ON COLUMN VM_PROMOCION_ANUAL.ASIGNATURAS_REPROBADAS IS 'Cantidad de asignaturas con DEFINITIVA < 3.0';
COMMENT ON COLUMN VM_PROMOCION_ANUAL.NOTA_MINIMA IS 'Nota definitiva mas baja del estudiante en el ano';
COMMENT ON COLUMN VM_PROMOCION_ANUAL.NOTA_MAXIMA IS 'Nota definitiva mas alta del estudiante en el ano';
COMMENT ON COLUMN VM_PROMOCION_ANUAL.ESTADO_PROMOCION IS 'Calculado: PROMOVIDO si existe TMATRICULA siguiente con FK_TMATRICULA_ANTERIOR apuntando a esta; NO_PROMOVIDO en caso contrario';
